/* ══════════════════════════════════════════════════════════════
   SOUL LINK — Undertale Launcher
   Original fan-made interface. Pixel system UI.
   ══════════════════════════════════════════════════════════════ */

@font-face {
  font-family: 'Press Start 2P';
  src: url('assets/fonts/PressStart2P-Regular.ttf') format('truetype');
  font-weight: 400;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: 'Pixelify Sans';
  src: url('assets/fonts/PixelifySans-Regular.ttf') format('truetype');
  font-weight: 400;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: 'Pixelify Sans';
  src: url('assets/fonts/PixelifySans-Bold.ttf') format('truetype');
  font-weight: 600 800;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: 'VT323';
  src: url('assets/fonts/VT323-Regular.ttf') format('truetype');
  font-weight: 400;
  font-style: normal;
  font-display: swap;
}

:root {
  --font-pixel: 'Press Start 2P', 'Pixelify Sans', monospace;
  --font-ui: 'Pixelify Sans', 'Trebuchet MS', sans-serif;
  --font-mono: 'VT323', 'Pixelify Sans', monospace;

  --ink: #07060d;
  --bg: #08060f;
  --bg-soft: #0d0a17;
  --panel: rgba(17, 12, 29, 0.9);
  --panel-solid: #120d20;
  --panel-raised: #171027;
  --line: #2b2142;
  --line-soft: #20182f;
  --line-bright: #49336b;
  --text: #f8f2ff;
  --text-soft: #d9cfe9;
  --muted: #9b8db9;
  --muted-dim: #6f6389;
  --red: #ff3355;
  --red-hot: #ff5370;
  --red-deep: #b3002f;
  --gold: #ffd75e;
  --gold-soft: #ffeaa4;
  --cyan: #7de3ff;
  --green: #6dffa8;
  --purple: #9b6bff;
  --orange: #ff9d5c;
  --shadow: 0 24px 60px rgba(0, 0, 0, 0.55);
  --mod-accent: var(--red);
  --mod-accent-2: var(--gold);
  --mod-glow: rgba(255, 51, 85, 0.28);
  --ease-snap: cubic-bezier(0.2, 0.9, 0.2, 1);
}

* { box-sizing: border-box; }

html {
  min-height: 100%;
  background: var(--bg);
  scroll-behavior: smooth;
}

body {
  margin: 0;
  min-height: 100dvh;
  color: var(--text);
  background:
    radial-gradient(ellipse 70% 50% at 18% 12%, rgba(89, 39, 123, 0.17), transparent 60%),
    radial-gradient(ellipse 55% 55% at 88% 76%, rgba(255, 51, 85, 0.08), transparent 62%),
    linear-gradient(160deg, #090711 0%, #07050d 54%, #0a0712 100%);
  font-family: var(--font-ui);
  font-size: 16px;
  line-height: 1.4;
  overflow-x: hidden;
  -webkit-tap-highlight-color: transparent;
  text-rendering: geometricPrecision;
}

body.is-playing { overflow: hidden; }

::selection { background: var(--red); color: #fff; }

button, input, select { font: inherit; color: inherit; }
button { cursor: pointer; }
button:disabled { cursor: not-allowed; opacity: 0.45; }
a { color: inherit; }
img { max-width: 100%; display: block; }
svg { display: block; }

h1, h2, h3, h4, p { margin: 0; }

:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 3px;
}

.sr-only {
  position: absolute !important;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0, 0, 0, 0);
  white-space: nowrap; border: 0;
}

.skip-link {
  position: fixed;
  top: -60px; left: 16px;
  z-index: 2000;
  padding: 12px 16px;
  background: var(--gold);
  color: var(--ink);
  font-weight: 700;
  text-decoration: none;
  transition: top 0.2s;
}
.skip-link:focus { top: 10px; }

.icon {
  width: 1em;
  height: 1em;
  fill: currentColor;
  shape-rendering: crispEdges;
  flex: none;
}
.icon .cut, .icon [class='cut'] { fill: var(--ink); }

/* ══════════════ Ambient world ══════════════ */

.ambient {
  position: fixed;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  overflow: hidden;
}
#ambient-canvas { width: 100%; height: 100%; opacity: 0.85; }
.ambient-haze {
  position: absolute;
  inset: -20%;
  background:
    radial-gradient(circle at 20% 20%, rgba(116, 67, 255, 0.08), transparent 32%),
    radial-gradient(circle at 76% 28%, rgba(255, 51, 85, 0.05), transparent 25%),
    radial-gradient(circle at 50% 100%, rgba(255, 215, 94, 0.035), transparent 38%);
  animation: haze-breathe 12s ease-in-out infinite;
}
.ambient-grain {
  position: absolute;
  inset: 0;
  opacity: 0.16;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='2' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.5'/%3E%3C/svg%3E");
  mix-blend-mode: soft-light;
}
.crt-lines {
  position: fixed;
  inset: 0;
  z-index: 3;
  pointer-events: none;
  opacity: 0.32;
  background: repeating-linear-gradient(
    to bottom,
    transparent 0,
    transparent 2px,
    rgba(0, 0, 0, 0.33) 3px,
    rgba(0, 0, 0, 0.33) 4px
  );
  mix-blend-mode: multiply;
}
body.no-scanlines .crt-lines,
body.reduce-motion .crt-lines { display: none; }

@keyframes haze-breathe {
  0%, 100% { transform: scale(1) translate3d(0, 0, 0); opacity: 1; }
  50% { transform: scale(1.06) translate3d(1%, -1%, 0); opacity: 0.72; }
}

/* ══════════════ Boot ══════════════ */

.boot-screen {
  position: fixed;
  inset: 0;
  z-index: 1000;
  display: grid;
  place-items: center;
  background:
    radial-gradient(circle at 50% 42%, #1a0d25 0%, #08060f 46%, #050409 100%);
  transition: opacity 0.55s ease, visibility 0.55s;
}
.boot-screen.is-done { opacity: 0; visibility: hidden; pointer-events: none; }
.boot-inner { width: min(360px, 82vw); text-align: center; }
.boot-mark {
  width: 82px; height: 82px;
  margin: 0 auto 26px;
  display: grid; place-items: center;
  border: 2px solid #3a2351;
  background: #100a19;
  box-shadow: 0 0 40px rgba(255, 51, 85, 0.22), inset 0 0 22px rgba(255, 51, 85, 0.12);
  animation: boot-thump 1.4s steps(2, end) infinite;
}
.boot-mark .icon { width: 38px; height: 38px; color: var(--red); filter: drop-shadow(0 0 10px var(--red)); }
.boot-word {
  font-family: var(--font-pixel);
  font-size: 19px;
  letter-spacing: 0.04em;
  margin-bottom: 28px;
  text-shadow: 3px 3px 0 #180a13;
}
.boot-word span { color: var(--red); }
.boot-line {
  height: 4px;
  background: #1e152c;
  overflow: hidden;
  margin-bottom: 12px;
}
.boot-line i {
  display: block;
  height: 100%;
  width: 38%;
  background: linear-gradient(90deg, var(--red-deep), var(--red), var(--gold));
  animation: boot-load 1.15s var(--ease-snap) infinite;
}
.boot-log {
  display: flex;
  justify-content: space-between;
  font-family: var(--font-mono);
  font-size: 15px;
  letter-spacing: 0.12em;
  color: var(--muted);
}
@keyframes boot-line { from { width: 0; } to { width: 100%; } }
@keyframes boot-load { 0% { transform: translateX(-110%); } 100% { transform: translateX(360%); } }
@keyframes boot-thump { 0%, 100% { transform: scale(1); } 50% { transform: scale(1.04); } }

/* ══════════════ Shell ══════════════ */

.app-frame {
  position: relative;
  z-index: 2;
  min-height: 100dvh;
  display: flex;
  flex-direction: column;
}

.topbar {
  position: sticky;
  top: 0;
  z-index: 40;
  height: 68px;
  display: flex;
  align-items: center;
  gap: 24px;
  padding: 0 clamp(18px, 3vw, 44px);
  border-bottom: 1px solid rgba(73, 51, 107, 0.5);
  background: rgba(8, 6, 15, 0.78);
  backdrop-filter: blur(14px) saturate(1.2);
}
.topbar::after {
  content: '';
  position: absolute;
  left: 0; right: 0; bottom: -1px;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(255, 51, 85, 0.4) 25%, transparent 60%);
}
.brand {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 0;
  border: 0;
  background: transparent;
}
.brand-heart {
  width: 30px; height: 30px;
  display: grid; place-items: center;
  background: #160c1b;
  border: 1px solid #3a1e2c;
  color: var(--red);
  box-shadow: 0 0 18px rgba(255, 51, 85, 0.12);
}
.brand-heart .icon { width: 15px; height: 15px; }
.brand-word {
  font-family: var(--font-pixel);
  font-size: 13px;
  letter-spacing: 0.02em;
  line-height: 1;
}
.brand-word span { color: var(--red); }
.brand-build {
  font-family: var(--font-mono);
  font-size: 14px;
  letter-spacing: 0.08em;
  color: var(--muted-dim);
  padding-left: 10px;
  border-left: 1px solid var(--line);
}
.topbar-center {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 14px;
  color: var(--muted-dim);
  font-size: 10px;
  letter-spacing: 0.24em;
  text-transform: uppercase;
  white-space: nowrap;
}
.topbar-tick { width: 20px; height: 1px; background: var(--line); }
.topbar-actions { display: flex; align-items: center; gap: 8px; }
.net-pill {
  display: flex;
  align-items: center;
  gap: 7px;
  height: 30px;
  padding: 0 10px;
  border: 1px solid var(--line);
  background: rgba(19, 13, 30, 0.8);
  color: var(--muted);
  font-size: 10px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}
.net-dot {
  width: 6px; height: 6px;
  background: var(--gold);
  box-shadow: 0 0 8px var(--gold);
  animation: pulse 1.6s steps(2, end) infinite;
}
.net-pill.is-online .net-dot { background: var(--green); box-shadow: 0 0 8px var(--green); }
.net-pill.is-offline .net-dot { background: var(--orange); box-shadow: 0 0 8px var(--orange); animation: none; }
.icon-btn {
  width: 34px; height: 34px;
  display: grid; place-items: center;
  border: 1px solid var(--line);
  background: rgba(19, 13, 30, 0.8);
  color: var(--muted);
  transition: color 0.15s, border-color 0.15s, background 0.15s;
}
.icon-btn:hover, .icon-btn:focus-visible {
  color: var(--text);
  border-color: var(--line-bright);
  background: var(--panel-raised);
}
.icon-btn .icon { width: 15px; height: 15px; }
#sound-toggle .icon-sound-off { display: none; }
body.is-muted #sound-toggle .icon-sound-on { display: none; }
body.is-muted #sound-toggle .icon-sound-off { display: block; }

.main-stage { flex: 1; position: relative; }
.view { animation: view-in 0.32s var(--ease-snap); }
.view[hidden] { display: none !important; }
@keyframes view-in {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}
body.reduce-motion .view { animation: none; }

/* ══════════════ Home ══════════════ */

.view-home { padding: clamp(20px, 3.2vw, 44px); }
.home-grid {
  width: min(1520px, 100%);
  margin: 0 auto;
  display: grid;
  grid-template-columns: minmax(0, 1.28fr) minmax(330px, 0.82fr) minmax(270px, 0.62fr);
  gap: clamp(16px, 2vw, 26px);
  align-items: stretch;
}

.hero-panel {
  position: relative;
  display: flex;
  flex-direction: column;
  justify-content: center;
  min-height: 560px;
  padding: clamp(8px, 1vw, 18px) 0;
}
.hero-panel::before {
  content: '';
  position: absolute;
  z-index: -1;
  width: 340px; height: 340px;
  left: -100px; top: 22%;
  border: 1px solid rgba(255, 51, 85, 0.08);
  transform: rotate(45deg);
  box-shadow: 0 0 120px rgba(255, 51, 85, 0.06) inset;
}
.eyebrow {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 24px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.2em;
  text-transform: uppercase;
}
.eyebrow-heart { color: var(--red); }
.eyebrow-heart .icon { width: 11px; height: 11px; }
.eyebrow-rule { width: 44px; height: 1px; background: var(--line-bright); }
.eyebrow-code { font-family: var(--font-mono); letter-spacing: 0.1em; color: var(--muted-dim); }

.hero-title {
  position: relative;
  margin: 0 0 26px;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  line-height: 0.94;
  user-select: none;
}
.hero-title-main {
  display: block;
  font-family: var(--font-pixel);
  font-size: clamp(36px, 4.7vw, 70px);
  letter-spacing: -0.035em;
  color: var(--text);
  text-shadow:
    0 0 34px rgba(255, 255, 255, 0.08),
    5px 5px 0 rgba(0, 0, 0, 0.78),
    8px 8px 0 rgba(179, 0, 47, 0.18);
  animation: title-drift 7s steps(60, end) infinite;
}
.hero-title-sub {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 14px;
  margin-top: 10px;
  margin-left: 3px;
  font-family: var(--font-pixel);
  font-size: clamp(20px, 2.5vw, 36px);
  letter-spacing: 0.07em;
  color: transparent;
  -webkit-text-stroke: 1.5px var(--red);
  text-shadow: 0 0 26px rgba(255, 51, 85, 0.2);
}
.hero-title-sub span { transform: translateX(2px); }
.hero-cursor {
  width: 13px; height: 23px;
  background: var(--red);
  box-shadow: 0 0 14px rgba(255, 51, 85, 0.5);
  animation: blink 1.05s steps(2, end) infinite;
}
@keyframes title-drift {
  0%, 100% { transform: translate(0, 0); }
  33% { transform: translate(1px, -1px); }
  66% { transform: translate(-1px, 1px); }
}
@keyframes blink { 0%, 49% { opacity: 1; } 50%, 100% { opacity: 0; } }

.hero-lede {
  max-width: 540px;
  color: var(--muted);
  font-size: clamp(15px, 1.1vw, 17px);
  line-height: 1.6;
  margin-bottom: 28px;
}

.soul-card {
  display: grid;
  grid-template-columns: 104px minmax(150px, 1fr) minmax(130px, 0.8fr);
  align-items: center;
  gap: 18px;
  width: min(590px, 100%);
  padding: 15px 18px;
  border: 1px solid var(--line);
  border-left: 2px solid var(--mod-accent, var(--red));
  background:
    linear-gradient(90deg, rgba(255, 51, 85, 0.06), transparent 34%),
    rgba(13, 9, 22, 0.78);
  box-shadow: 8px 8px 0 rgba(4, 3, 9, 0.42);
}
.soul-chamber {
  position: relative;
  width: 84px; height: 84px;
  display: grid; place-items: center;
  background: radial-gradient(circle, rgba(255, 51, 85, 0.16), transparent 66%);
}
.soul-rings, .soul-rings::before, .soul-rings::after {
  position: absolute;
  inset: 0;
  border: 1px solid rgba(255, 51, 85, 0.18);
  transform: rotate(45deg);
  content: '';
}
.soul-rings::before { inset: 9px; border-color: rgba(255, 51, 85, 0.12); }
.soul-rings::after { inset: 20px; border-color: rgba(255, 51, 85, 0.08); }
.soul-heart {
  position: relative;
  z-index: 1;
  width: 32px; height: 32px;
  color: var(--red);
  filter: drop-shadow(0 0 10px rgba(255, 51, 85, 0.75));
  animation: heart-float 2.4s steps(4, end) infinite;
}
@keyframes heart-float {
  0%, 100% { transform: translateY(0) scale(1); }
  50% { transform: translateY(-4px) scale(1.06); }
}
.soul-spark {
  position: absolute;
  width: 3px; height: 3px;
  background: var(--gold);
  opacity: 0;
  animation: spark 3.4s steps(1, end) infinite;
}
.sp1 { top: 12px; right: 13px; animation-delay: 0.4s; }
.sp2 { bottom: 17px; left: 12px; animation-delay: 1.7s; }
.sp3 { top: 25px; left: 4px; animation-delay: 2.6s; }
@keyframes spark {
  0%, 80%, 100% { opacity: 0; transform: scale(0); }
  84% { opacity: 1; transform: scale(1); }
  92% { opacity: 0; transform: scale(0.4); }
}
.soul-copy { display: flex; flex-direction: column; gap: 5px; min-width: 0; }
.micro-label {
  color: var(--muted-dim);
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}
.soul-state { font-size: 20px; letter-spacing: 0.05em; color: var(--text); }
.soul-meter { display: flex; gap: 3px; margin: 2px 0; }
.soul-meter i {
  width: 14px; height: 4px;
  background: var(--red);
  box-shadow: 0 0 6px rgba(255, 51, 85, 0.35);
}
.soul-meter i:nth-child(n+7) { background: #38213f; box-shadow: none; }
.soul-note { font-family: var(--font-mono); font-size: 14px; color: var(--muted); }
.soul-mod {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
  padding-left: 16px;
  border-left: 1px solid var(--line);
}
.soul-mod-name {
  font-size: 14px;
  font-weight: 700;
  line-height: 1.2;
  overflow: hidden;
  text-overflow: ellipsis;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  color: var(--mod-accent, var(--red));
}
.soul-mod-meta {
  font-family: var(--font-mono);
  font-size: 13px;
  letter-spacing: 0.08em;
  color: var(--muted-dim);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.hero-badges { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 24px; }
.badge {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  height: 28px;
  padding: 0 10px;
  border: 1px solid var(--line-soft);
  background: rgba(15, 10, 24, 0.6);
  color: var(--muted);
  font-family: var(--font-mono);
  font-size: 13px;
  letter-spacing: 0.07em;
  text-decoration: none;
  transition: border-color 0.15s, color 0.15s;
}
.badge .icon { width: 12px; height: 12px; }
.badge:hover { color: var(--text); border-color: var(--line-bright); }
.badge-apk { color: var(--green); border-color: rgba(109, 255, 168, 0.22); }
.badge-apk:hover { color: #c6ffdc; border-color: var(--green); }

/* Menu panel */

.menu-panel {
  position: relative;
  display: flex;
  flex-direction: column;
  padding: 20px;
  border: 1px solid var(--line);
  background:
    linear-gradient(145deg, rgba(255, 51, 85, 0.045), transparent 30%),
    linear-gradient(180deg, rgba(21, 14, 35, 0.93), rgba(11, 8, 19, 0.94));
  box-shadow: 0 22px 70px rgba(0, 0, 0, 0.4), inset 0 1px 0 rgba(255, 255, 255, 0.035);
}
.menu-panel::before, .menu-panel::after {
  content: '';
  position: absolute;
  width: 13px; height: 13px;
  border-color: var(--line-bright);
  border-style: solid;
  pointer-events: none;
}
.menu-panel::before { top: -1px; left: -1px; border-width: 2px 0 0 2px; }
.menu-panel::after { bottom: -1px; right: -1px; border-width: 0 2px 2px 0; }
.panel-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  min-height: 28px;
  padding-bottom: 14px;
  border-bottom: 1px solid var(--line-soft);
  color: var(--text-soft);
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}
.panel-head > span:first-child { display: inline-flex; align-items: center; gap: 9px; }
.panel-head .icon { width: 13px; height: 13px; color: var(--red); }
.panel-head-meta { color: var(--muted-dim); font-family: var(--font-mono); font-size: 13px; letter-spacing: 0.1em; }
.panel-head-meta b { color: var(--text-soft); }

.main-menu { display: flex; flex-direction: column; gap: 9px; margin: 16px 0; flex: 1; }
.menu-item {
  position: relative;
  display: grid;
  grid-template-columns: 24px 40px minmax(0, 1fr) auto;
  align-items: center;
  gap: 13px;
  min-height: 92px;
  padding: 14px 14px 14px 18px;
  text-align: left;
  border: 1px solid var(--line);
  background:
    linear-gradient(90deg, rgba(255, 51, 85, 0.04), transparent 42%),
    rgba(17, 12, 28, 0.68);
  color: var(--text);
  overflow: hidden;
  transition: transform 0.18s var(--ease-snap), border-color 0.18s, background 0.18s, box-shadow 0.18s;
}
.menu-rail {
  position: absolute;
  left: 0; top: 50%;
  width: 3px; height: 0;
  background: var(--red);
  transform: translateY(-50%);
  transition: height 0.22s var(--ease-snap);
  box-shadow: 0 0 14px var(--red);
}
.menu-index {
  font-family: var(--font-mono);
  font-size: 15px;
  color: var(--muted-dim);
  letter-spacing: 0.08em;
  transition: color 0.18s;
}
.menu-icon {
  width: 38px; height: 38px;
  display: grid; place-items: center;
  border: 1px solid var(--line);
  background: rgba(7, 5, 12, 0.42);
  color: var(--muted);
  transition: color 0.18s, border-color 0.18s, background 0.18s, transform 0.18s;
}
.menu-icon .icon { width: 17px; height: 17px; }
.menu-copy { display: flex; flex-direction: column; gap: 5px; min-width: 0; }
.menu-title { font-size: 21px; font-weight: 700; line-height: 1; letter-spacing: 0.04em; }
.menu-sub { color: var(--muted); font-size: 12.5px; line-height: 1.2; transition: color 0.18s; }
.menu-go {
  display: flex;
  align-items: center;
  gap: 7px;
  color: var(--muted-dim);
  font-family: var(--font-mono);
  font-size: 12px;
  letter-spacing: 0.1em;
  transition: color 0.18s, transform 0.18s;
}
.menu-go .icon { width: 11px; height: 11px; }
.menu-item:hover, .menu-item:focus-visible {
  border-color: rgba(255, 51, 85, 0.62);
  background:
    linear-gradient(90deg, rgba(255, 51, 85, 0.14), rgba(255, 51, 85, 0.035) 46%, transparent),
    rgba(23, 14, 31, 0.88);
  transform: translateX(5px);
  box-shadow: -5px 0 0 rgba(255, 51, 85, 0.1), 0 0 34px rgba(255, 51, 85, 0.07);
  outline: none;
}
.menu-item:hover .menu-rail, .menu-item:focus-visible .menu-rail { height: 58%; }
.menu-item:hover .menu-index, .menu-item:focus-visible .menu-index { color: var(--red); }
.menu-item:hover .menu-icon, .menu-item:focus-visible .menu-icon {
  color: var(--red);
  border-color: rgba(255, 51, 85, 0.45);
  background: rgba(255, 51, 85, 0.07);
  transform: translateY(-1px);
}
.menu-item:hover .menu-sub, .menu-item:focus-visible .menu-sub { color: var(--text-soft); }
.menu-item:hover .menu-go, .menu-item:focus-visible .menu-go { color: var(--red); transform: translateX(2px); }
.menu-item.is-bump { animation: menu-bump 0.18s steps(2, end); }
@keyframes menu-bump { 50% { transform: translateX(7px); } }
.menu-foot {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding-top: 13px;
  border-top: 1px solid var(--line-soft);
  color: var(--muted-dim);
  font-family: var(--font-mono);
  font-size: 12.5px;
  letter-spacing: 0.08em;
}
.menu-foot span { display: inline-flex; align-items: center; gap: 5px; }
kbd {
  display: inline-grid;
  place-items: center;
  min-width: 19px; height: 19px;
  padding: 0 4px;
  border: 1px solid var(--line-bright);
  background: #0a0711;
  color: var(--text-soft);
  font-family: var(--font-mono);
  font-size: 12px;
  line-height: 1;
  box-shadow: 0 2px 0 #05040a;
}

/* Rail */

.home-rail { display: flex; flex-direction: column; gap: 13px; }
.rail-card {
  position: relative;
  border: 1px solid var(--line);
  background: rgba(14, 10, 23, 0.88);
}
.rail-label {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 11px 13px;
  border-bottom: 1px solid var(--line-soft);
  color: var(--muted);
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}
.rail-label-code { margin-left: auto; font-family: var(--font-mono); color: var(--red); font-size: 12px; }
.pulse-dot, .live-tag i, .status-net i, .api-state i, .save-state i {
  display: inline-block;
  width: 6px; height: 6px;
  background: var(--green);
  box-shadow: 0 0 8px var(--green);
  animation: pulse 1.8s steps(2, end) infinite;
}
@keyframes pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.32; } }

.featured-media {
  position: relative;
  display: block;
  width: 100%;
  aspect-ratio: 16 / 9;
  padding: 0;
  border: 0;
  overflow: hidden;
  background: #100b1c;
}
.featured-media img {
  width: 100%; height: 100%;
  object-fit: cover;
  filter: saturate(0.82) contrast(1.05);
  transition: transform 0.5s var(--ease-snap), filter 0.3s;
}
.featured-media:hover img { transform: scale(1.035); filter: saturate(1) contrast(1.02); }
.media-skeleton {
  position: absolute;
  inset: 0;
  background: linear-gradient(100deg, #120d1e 20%, #241832 45%, #120d1e 70%);
  background-size: 240% 100%;
  animation: shimmer 1.6s linear infinite;
}
.featured-media.has-image .media-skeleton { display: none; }
@keyframes shimmer { from { background-position: 130% 0; } to { background-position: -130% 0; } }
.media-scan {
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 45%, rgba(7, 5, 12, 0.62));
  pointer-events: none;
}
.featured-source {
  position: absolute;
  left: 10px; bottom: 9px;
  padding: 3px 6px;
  border: 1px solid rgba(255, 255, 255, 0.18);
  background: rgba(5, 4, 9, 0.72);
  color: var(--text-soft);
  font-family: var(--font-mono);
  font-size: 11px;
  letter-spacing: 0.12em;
}
.featured-body { padding: 13px; }
.featured-title {
  font-size: 17px;
  line-height: 1.16;
  font-weight: 700;
  letter-spacing: 0.01em;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  margin-bottom: 6px;
}
.featured-meta {
  display: flex;
  align-items: center;
  gap: 7px;
  margin-bottom: 10px;
  color: var(--muted);
  font-family: var(--font-mono);
  font-size: 13px;
  white-space: nowrap;
  overflow: hidden;
}
.featured-meta span:not(.dot-sep) { overflow: hidden; text-overflow: ellipsis; }
.dot-sep { width: 3px; height: 3px; background: var(--muted-dim); flex: none; }
.featured-stats {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 12px;
  color: var(--muted);
  font-family: var(--font-mono);
  font-size: 13px;
}
.featured-stats span { display: inline-flex; align-items: center; gap: 5px; }
.featured-stats .icon { width: 11px; height: 11px; }
.featured-stats b { font-weight: 400; color: var(--text-soft); }
.featured-version {
  margin-left: auto;
  padding: 2px 5px;
  border: 1px solid var(--line);
  color: var(--muted);
  font-size: 11px;
}

.community-card { padding: 13px; }
.community-head { display: flex; align-items: center; justify-content: space-between; margin-bottom: 10px; }
.live-tag {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--green);
  font-family: var(--font-mono);
  font-size: 12px;
  letter-spacing: 0.1em;
}
.live-tag i { width: 5px; height: 5px; }
.community-stat { display: flex; align-items: baseline; gap: 8px; margin-bottom: 9px; }
.community-stat b { font-family: var(--font-pixel); font-size: 24px; color: var(--text); line-height: 1; }
.community-stat span { color: var(--muted); font-size: 12px; }
.community-bars {
  display: flex;
  gap: 3px;
  align-items: flex-end;
  height: 24px;
  margin-bottom: 12px;
  opacity: 0.7;
}
.community-bars i {
  flex: 1;
  background: linear-gradient(180deg, var(--red), rgba(255, 51, 85, 0.18));
  height: calc(var(--h, 40%) * 1%);
  animation: bars 2.6s steps(4, end) infinite alternate;
}
.community-bars i:nth-child(1) { --h: 28; animation-delay: -0.2s; }
.community-bars i:nth-child(2) { --h: 54; animation-delay: -1.1s; }
.community-bars i:nth-child(3) { --h: 36; animation-delay: -0.7s; }
.community-bars i:nth-child(4) { --h: 76; animation-delay: -1.8s; }
.community-bars i:nth-child(5) { --h: 44; animation-delay: -0.4s; }
.community-bars i:nth-child(6) { --h: 90; animation-delay: -1.4s; }
.community-bars i:nth-child(7) { --h: 58; animation-delay: -0.9s; }
.community-bars i:nth-child(8) { --h: 72; animation-delay: -2.1s; }
.community-bars i:nth-child(9) { --h: 40; animation-delay: -0.3s; }
.community-bars i:nth-child(10) { --h: 84; animation-delay: -1.6s; }
.community-bars i:nth-child(11) { --h: 50; animation-delay: -0.6s; }
.community-bars i:nth-child(12) { --h: 64; animation-delay: -1.9s; }
@keyframes bars { from { transform: scaleY(0.72); } to { transform: scaleY(1); } }
.text-link {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--text-soft);
  font-family: var(--font-mono);
  font-size: 14px;
  letter-spacing: 0.04em;
  text-decoration: none;
  transition: color 0.15s, gap 0.15s;
}
.text-link .icon { width: 10px; height: 10px; color: var(--red); }
.text-link:hover { color: var(--red-hot); gap: 10px; }

.apk-card {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 12px 13px;
  text-decoration: none;
  transition: border-color 0.18s, background 0.18s, transform 0.18s;
}
.apk-card:hover {
  border-color: rgba(109, 255, 168, 0.45);
  background: rgba(109, 255, 168, 0.035);
  transform: translateY(-2px);
}
.apk-icon {
  width: 38px; height: 38px;
  display: grid; place-items: center;
  border: 1px solid rgba(109, 255, 168, 0.28);
  background: rgba(109, 255, 168, 0.06);
  color: var(--green);
}
.apk-icon .icon { width: 18px; height: 18px; }
.apk-copy { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.apk-copy strong { font-size: 14px; letter-spacing: 0.02em; }
.apk-copy span:last-child { color: var(--muted); font-family: var(--font-mono); font-size: 13px; }
.apk-dl { margin-left: auto; color: var(--green); width: 14px; height: 14px; }

/* Generic pixel buttons */

.pixel-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 38px;
  padding: 0 15px;
  border: 1px solid var(--line-bright);
  background: #171025;
  color: var(--text);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.09em;
  text-transform: uppercase;
  text-decoration: none;
  box-shadow: 4px 4px 0 #05040a;
  transition: background 0.14s, border-color 0.14s, transform 0.1s, box-shadow 0.1s, color 0.14s;
}
.pixel-button .icon { width: 13px; height: 13px; }
.pixel-button:hover { background: #221535; border-color: var(--text-soft); }
.pixel-button:active { transform: translate(3px, 3px); box-shadow: 1px 1px 0 #05040a; }
.pixel-button.primary {
  border-color: var(--red);
  background: var(--red);
  color: #fff;
  text-shadow: 0 1px 0 rgba(0, 0, 0, 0.25);
  box-shadow: 4px 4px 0 #560018;
}
.pixel-button.primary:hover { background: var(--red-hot); border-color: var(--red-hot); }
.pixel-button.small { min-height: 32px; padding: 0 11px; font-size: 10px; box-shadow: 3px 3px 0 #05040a; }
.pixel-button.full { width: 100%; }
.pixel-button.ghost { background: transparent; border-color: var(--line); color: var(--muted); box-shadow: none; }
.pixel-button.ghost:hover { color: var(--text); background: rgba(255, 255, 255, 0.03); }
.pixel-button.danger { border-color: rgba(255, 51, 85, 0.6); background: rgba(255, 51, 85, 0.08); color: var(--red-hot); }
.pixel-button.danger:hover { background: rgba(255, 51, 85, 0.16); }
.pixel-button[disabled] { opacity: 0.45; pointer-events: none; }

/* ══════════════ Statusbar ══════════════ */

.statusbar {
  position: relative;
  z-index: 35;
  min-height: 34px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 0 clamp(14px, 3vw, 44px);
  border-top: 1px solid rgba(73, 51, 107, 0.4);
  background: rgba(7, 5, 12, 0.75);
  color: var(--muted-dim);
  font-family: var(--font-mono);
  font-size: 13px;
  letter-spacing: 0.06em;
}
.status-left, .status-center, .status-right { display: flex; align-items: center; gap: 9px; white-space: nowrap; }
.status-left { color: var(--muted); }
.status-center .icon { width: 8px; height: 8px; color: var(--red); }
.status-sep { width: 1px; height: 11px; background: var(--line); }
.status-link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--muted);
  font: inherit;
  letter-spacing: inherit;
}
.status-link b { color: var(--red); font-weight: 400; }
.status-link:hover { color: var(--text); }
.status-net { display: inline-flex; align-items: center; gap: 6px; }
.status-net i { width: 5px; height: 5px; background: var(--gold); box-shadow: 0 0 6px var(--gold); }
.status-net.is-online i { background: var(--green); box-shadow: 0 0 6px var(--green); }
.status-net.is-offline i { background: var(--orange); box-shadow: none; }

/* ══════════════ Page shell (settings / mods) ══════════════ */

.view-page { padding: clamp(20px, 3vw, 42px); }
.page-shell { width: min(1320px, 100%); margin: 0 auto; }
.page-head {
  display: flex;
  align-items: center;
  gap: clamp(14px, 2vw, 28px);
  margin-bottom: 24px;
  padding-bottom: 20px;
  border-bottom: 1px solid var(--line);
}
.back-button {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  height: 34px;
  padding: 0 12px;
  border: 1px solid var(--line);
  background: rgba(19, 13, 30, 0.7);
  color: var(--muted);
  font-family: var(--font-mono);
  font-size: 13px;
  letter-spacing: 0.08em;
  transition: color 0.15s, border-color 0.15s;
}
.back-button .icon { width: 11px; height: 11px; }
.back-button:hover { color: var(--text); border-color: var(--line-bright); }
.page-head-copy { flex: 1; min-width: 0; }
.page-kicker {
  display: block;
  margin-bottom: 6px;
  color: var(--red);
  font-family: var(--font-mono);
  font-size: 12px;
  letter-spacing: 0.16em;
}
.page-head h2 {
  font-family: var(--font-pixel);
  font-size: clamp(20px, 2.4vw, 32px);
  letter-spacing: 0.01em;
  line-height: 1.15;
}
html[data-lang='ru'] .page-head h2 { font-family: var(--font-ui); font-weight: 700; letter-spacing: 0.06em; }
.page-head-side { display: flex; align-items: center; gap: 14px; }
.save-state, .api-state {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  color: var(--muted-dim);
  font-family: var(--font-mono);
  font-size: 12px;
  letter-spacing: 0.08em;
}
.api-state.is-online { color: var(--green); }
.api-state.is-offline { color: var(--orange); }
.api-state.is-online i { background: var(--green); box-shadow: 0 0 7px var(--green); }
.api-state.is-offline i { background: var(--orange); box-shadow: none; animation: none; }
.page-footer {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-top: 24px;
  padding-top: 16px;
  border-top: 1px solid var(--line-soft);
  color: var(--muted-dim);
  font-size: 12px;
}
.page-footer p { flex: 1; line-height: 1.5; }
.version-chip {
  flex: none;
  padding: 4px 8px;
  border: 1px solid var(--line);
  color: var(--muted);
  font-family: var(--font-mono);
  font-size: 11px;
  letter-spacing: 0.08em;
  white-space: nowrap;
}

/* Settings */

.settings-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px;
}
.panel {
  position: relative;
  border: 1px solid var(--line);
  background:
    linear-gradient(150deg, rgba(255, 51, 85, 0.025), transparent 35%),
    rgba(14, 10, 23, 0.86);
  box-shadow: 5px 5px 0 rgba(4, 3, 9, 0.3);
}
.panel > .panel-head { padding: 15px 18px 12px; }
.settings-panel { padding-bottom: 6px; }
.settings-panel.wide { grid-column: 1 / -1; }
.setting-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  min-height: 60px;
  padding: 12px 18px;
  border-top: 1px solid var(--line-soft);
}
.setting-copy { display: flex; flex-direction: column; gap: 3px; min-width: 0; }
.setting-copy label, .setting-copy > span:first-child { font-size: 14.5px; color: var(--text-soft); }
.setting-copy > span:last-child { color: var(--muted-dim); font-size: 12px; line-height: 1.35; }
.switch {
  position: relative;
  width: 46px; height: 24px;
  flex: none;
  border: 1px solid var(--line-bright);
  background: #0b0813;
  padding: 0;
  transition: background 0.18s, border-color 0.18s;
}
.switch span {
  position: absolute;
  top: 3px; left: 3px;
  width: 16px; height: 16px;
  background: var(--muted-dim);
  transition: transform 0.18s var(--ease-snap), background 0.18s, box-shadow 0.18s;
}
.switch[aria-checked='true'] { background: rgba(255, 51, 85, 0.16); border-color: var(--red); }
.switch[aria-checked='true'] span {
  transform: translateX(22px);
  background: var(--red);
  box-shadow: 0 0 9px rgba(255, 51, 85, 0.7);
}
.slider-wrap { display: flex; align-items: center; gap: 10px; flex: none; width: min(230px, 45%); }
input[type='range'] {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 4px;
  background: linear-gradient(90deg, var(--red) var(--fill, 50%), #241a36 var(--fill, 50%));
  outline: none;
}
input[type='range']::-webkit-slider-thumb {
  -webkit-appearance: none;
  width: 14px; height: 18px;
  border: 1px solid #ff9cac;
  background: var(--red);
  box-shadow: 0 0 10px rgba(255, 51, 85, 0.5), -2px 2px 0 #4b0016;
  cursor: pointer;
}
input[type='range']::-moz-range-thumb {
  width: 14px; height: 18px;
  border-radius: 0;
  border: 1px solid #ff9cac;
  background: var(--red);
  box-shadow: 0 0 10px rgba(255, 51, 85, 0.5);
  cursor: pointer;
}
.slider-wrap output {
  width: 36px;
  text-align: right;
  color: var(--muted);
  font-family: var(--font-mono);
  font-size: 15px;
}
.segmented { display: inline-flex; border: 1px solid var(--line); flex: none; }
.segmented button {
  min-width: 42px;
  height: 30px;
  padding: 0 10px;
  border: 0;
  border-right: 1px solid var(--line);
  background: #0c0914;
  color: var(--muted);
  font-family: var(--font-mono);
  font-size: 14px;
  letter-spacing: 0.08em;
}
.segmented button:last-child { border-right: 0; }
.segmented button.is-active { background: var(--red); color: #fff; }

.android-panel { display: flex; flex-direction: column; }
.android-hero { display: flex; gap: 14px; padding: 16px 18px 14px; }
.android-mark {
  width: 52px; height: 52px;
  flex: none;
  display: grid; place-items: center;
  border: 1px solid rgba(109, 255, 168, 0.3);
  background: rgba(109, 255, 168, 0.06);
  color: var(--green);
  box-shadow: 0 0 24px rgba(109, 255, 168, 0.07);
}
.android-mark .icon { width: 26px; height: 26px; }
.android-hero strong { display: block; margin-bottom: 4px; font-size: 15px; }
.android-hero p { color: var(--muted); font-size: 12.5px; line-height: 1.45; }
.android-panel .pixel-button { width: calc(100% - 36px); margin: 0 18px; }
.fine-print { padding: 9px 18px 14px; color: var(--muted-dim); font-size: 11px; line-height: 1.35; }
.data-summary {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1px;
  margin: 0 18px 6px;
  border: 1px solid var(--line-soft);
  background: var(--line-soft);
}
.data-summary > div {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 12px;
  background: #0d0916;
}
.data-summary span { color: var(--muted-dim); font-size: 11px; }
.data-summary b { font-family: var(--font-mono); font-size: 20px; color: var(--text-soft); font-weight: 400; }
.data-summary b.is-accent { color: var(--mod-accent); }
.data-panel .setting-row { border-top: 0; }

/* ══════════════ Mods ══════════════ */

.mods-head { margin-bottom: 18px; }
.mods-head-side { flex-wrap: wrap; justify-content: flex-end; }
.mods-banner {
  position: relative;
  display: flex;
  align-items: center;
  gap: 26px;
  margin-bottom: 18px;
  padding: clamp(18px, 2.2vw, 30px);
  border: 1px solid var(--line);
  background:
    linear-gradient(100deg, rgba(155, 107, 255, 0.13), transparent 40%),
    radial-gradient(circle at 90% 20%, rgba(255, 51, 85, 0.11), transparent 40%),
    rgba(14, 10, 23, 0.9);
  overflow: hidden;
}
.mods-banner::after {
  content: 'MODS';
  position: absolute;
  right: 20px;
  bottom: -27px;
  font-family: var(--font-pixel);
  font-size: 92px;
  line-height: 1;
  color: rgba(255, 255, 255, 0.022);
  letter-spacing: -0.06em;
  pointer-events: none;
}
.mods-banner-copy { flex: 1; min-width: 0; }
.mods-banner-kicker {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  margin-bottom: 8px;
  color: var(--purple);
  font-family: var(--font-mono);
  font-size: 12px;
  letter-spacing: 0.14em;
}
.mods-banner-kicker .icon { width: 11px; height: 11px; }
.mods-banner h3 { font-size: clamp(20px, 2vw, 28px); line-height: 1.1; margin-bottom: 7px; }
.mods-banner p { max-width: 660px; color: var(--muted); font-size: 13px; line-height: 1.5; }
.mods-banner-stats { display: flex; align-items: stretch; gap: 1px; background: var(--line); flex: none; }
.mods-banner-stats > span {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 4px;
  min-width: 90px;
  padding: 10px 14px;
  background: rgba(9, 6, 15, 0.75);
}
.mods-banner-stats b { font-family: var(--font-pixel); font-size: 19px; line-height: 1; }
.mods-banner-stats small { color: var(--muted-dim); font-family: var(--font-mono); font-size: 10px; letter-spacing: 0.08em; }
.banner-status { align-items: center !important; color: var(--green); }
.banner-status small { color: var(--green); }
.banner-status .pulse-dot { margin-bottom: 2px; }

.mods-toolbar {
  display: flex;
  align-items: center;
  gap: 16px;
  flex-wrap: wrap;
  padding-bottom: 14px;
  border-bottom: 1px solid var(--line-soft);
}
.tabs { display: inline-flex; gap: 4px; }
.tab {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  height: 38px;
  padding: 0 14px;
  border: 1px solid transparent;
  background: transparent;
  color: var(--muted);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.1em;
}
.tab .icon { width: 13px; height: 13px; }
.tab:hover { color: var(--text); }
.tab.is-active { border-color: var(--line); background: var(--panel-raised); color: var(--text); }
.tab.is-active .icon { color: var(--red); }
.tab-count {
  display: inline-grid;
  place-items: center;
  min-width: 18px; height: 17px;
  padding: 0 4px;
  background: var(--red);
  color: #fff;
  font-family: var(--font-mono);
  font-size: 12px;
  font-weight: 400;
}
.mods-tools { display: flex; align-items: center; gap: 8px; margin-left: auto; }
.search-box {
  display: flex;
  align-items: center;
  gap: 8px;
  width: min(280px, 42vw);
  height: 36px;
  padding: 0 10px;
  border: 1px solid var(--line);
  background: rgba(9, 6, 15, 0.8);
  color: var(--muted);
}
.search-box:focus-within { border-color: var(--line-bright); color: var(--text); }
.search-box .icon { width: 13px; height: 13px; }
.search-box input {
  flex: 1;
  min-width: 0;
  border: 0;
  background: transparent;
  outline: 0;
  color: var(--text);
  font-size: 13px;
}
.search-box input::placeholder { color: var(--muted-dim); }
.search-box kbd { height: 17px; min-width: 17px; font-size: 11px; color: var(--muted-dim); }
.select-box { position: relative; display: flex; align-items: center; height: 36px; border: 1px solid var(--line); background: rgba(9, 6, 15, 0.8); }
.select-box select {
  appearance: none;
  height: 100%;
  padding: 0 30px 0 10px;
  border: 0;
  background: transparent;
  color: var(--muted);
  font-size: 12px;
  outline: 0;
}
.select-box .icon { position: absolute; right: 10px; width: 9px; height: 9px; color: var(--muted-dim); transform: rotate(90deg); pointer-events: none; }
.filter-row { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; padding: 13px 0 18px; }
.chip {
  height: 26px;
  padding: 0 10px;
  border: 1px solid var(--line-soft);
  background: transparent;
  color: var(--muted);
  font-family: var(--font-mono);
  font-size: 12px;
  letter-spacing: 0.06em;
  transition: color 0.15s, border-color 0.15s, background 0.15s;
}
.chip:hover { color: var(--text); border-color: var(--line-bright); }
.chip.is-active { border-color: var(--red); background: rgba(255, 51, 85, 0.1); color: var(--red-hot); }
.filter-spacer { flex: 1; }
.source-note { display: inline-flex; align-items: center; gap: 6px; color: var(--muted-dim); font-family: var(--font-mono); font-size: 12px; }
.source-note .icon { width: 10px; height: 10px; color: var(--green); }

.mods-pane { display: none; }
.mods-pane.is-active { display: block; animation: view-in 0.25s var(--ease-snap); }
.mod-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 14px;
}
.mod-card {
  position: relative;
  display: flex;
  flex-direction: column;
  border: 1px solid var(--line);
  background: rgba(13, 9, 22, 0.9);
  transition: transform 0.18s var(--ease-snap), border-color 0.18s, box-shadow 0.18s;
  overflow: hidden;
}
.mod-card:hover {
  transform: translateY(-3px);
  border-color: var(--line-bright);
  box-shadow: 0 14px 34px rgba(0, 0, 0, 0.35), 0 0 0 1px rgba(255, 51, 85, 0.08);
}
.mod-thumb {
  position: relative;
  display: block;
  width: 100%;
  aspect-ratio: 16 / 8.4;
  padding: 0;
  border: 0;
  background: #0e0a19;
  overflow: hidden;
}
.mod-thumb img { width: 100%; height: 100%; object-fit: cover; filter: saturate(0.82); transition: transform 0.45s var(--ease-snap), filter 0.25s; }
.mod-card:hover .mod-thumb img { transform: scale(1.04); filter: saturate(1); }
.mod-thumb::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 45%, rgba(7, 5, 12, 0.88));
  pointer-events: none;
}
.mod-thumb .thumb-fallback {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  background:
    linear-gradient(135deg, rgba(155, 107, 255, 0.12), transparent 45%),
    repeating-linear-gradient(45deg, #100b1d 0 8px, #130d22 8px 16px);
  color: var(--line-bright);
}
.thumb-fallback .icon { width: 34px; height: 34px; opacity: 0.7; }
.mod-thumb.is-broken img { display: none; }
.mod-badges { position: absolute; left: 9px; top: 9px; z-index: 1; display: flex; gap: 5px; }
.mod-badge {
  padding: 3px 6px;
  border: 1px solid rgba(255, 255, 255, 0.15);
  background: rgba(5, 4, 9, 0.78);
  color: var(--text-soft);
  font-family: var(--font-mono);
  font-size: 10px;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  backdrop-filter: blur(2px);
}
.mod-badge.installed { border-color: rgba(109, 255, 168, 0.4); color: var(--green); }
.mod-id {
  position: absolute;
  right: 9px; bottom: 8px;
  z-index: 1;
  color: rgba(255, 255, 255, 0.56);
  font-family: var(--font-mono);
  font-size: 11px;
  letter-spacing: 0.06em;
}
.mod-body { display: flex; flex-direction: column; gap: 4px; padding: 12px 13px 13px; flex: 1; }
.mod-title {
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  font-size: 15px;
  line-height: 1.2;
  font-weight: 700;
}
.mod-author { color: var(--muted); font-family: var(--font-mono); font-size: 13px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.mod-meta {
  display: flex;
  align-items: center;
  gap: 9px;
  margin-top: 2px;
  color: var(--muted-dim);
  font-family: var(--font-mono);
  font-size: 12px;
}
.mod-meta span { display: inline-flex; align-items: center; gap: 4px; }
.mod-meta .icon { width: 10px; height: 10px; }
.mod-actions { display: flex; gap: 6px; margin-top: 9px; padding-top: 10px; border-top: 1px solid var(--line-soft); }
.mod-actions .pixel-button { flex: 1; min-height: 30px; font-size: 10px; box-shadow: 2px 2px 0 #05040a; }
.mod-actions .pixel-button.icon-only { flex: 0 0 32px; padding: 0; }
.mod-skeleton {
  height: 292px;
  border: 1px solid var(--line-soft);
  background: linear-gradient(100deg, #0d0918 20%, #171023 45%, #0d0918 70%);
  background-size: 240% 100%;
  animation: shimmer 1.6s linear infinite;
}
.mods-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 280px;
  padding: 40px 20px;
  border: 1px dashed var(--line);
  background: rgba(10, 7, 17, 0.4);
  text-align: center;
}
.empty-heart {
  width: 54px; height: 54px;
  display: grid; place-items: center;
  margin-bottom: 4px;
  border: 1px solid var(--line);
  color: var(--muted-dim);
  background: #0b0813;
}
.empty-heart .icon { width: 22px; height: 22px; }
.mods-empty h3 { font-size: 18px; }
.mods-empty p { max-width: 370px; color: var(--muted); font-size: 13px; margin-bottom: 10px; }
.load-more-wrap { display: flex; justify-content: center; padding: 24px 0 4px; }
.load-more-wrap[hidden] { display: none; }

/* Installed */

.import-panel {
  position: relative;
  display: flex;
  align-items: center;
  gap: 20px;
  justify-content: space-between;
  margin-bottom: 14px;
  padding: 18px;
  border: 1px dashed var(--line-bright);
  background: rgba(14, 10, 23, 0.8);
  overflow: hidden;
}
.import-panel.is-drag { border-color: var(--red); background: rgba(255, 51, 85, 0.06); }
.import-copy { display: flex; align-items: center; gap: 13px; min-width: 0; }
.import-icon {
  width: 44px; height: 44px;
  flex: none;
  display: grid; place-items: center;
  border: 1px solid var(--line);
  background: #0b0813;
  color: var(--muted);
}
.import-icon .icon { width: 18px; height: 18px; }
.import-copy strong { display: block; margin-bottom: 3px; font-size: 15px; }
.import-copy p { color: var(--muted); font-size: 12.5px; }
.import-actions { display: flex; gap: 8px; flex: none; }
.drop-overlay {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  background: rgba(8, 6, 15, 0.88);
  color: var(--red);
  font-family: var(--font-mono);
  font-size: 16px;
  letter-spacing: 0.1em;
  border: 2px solid var(--red);
}
.drop-overlay .icon { width: 18px; height: 18px; }
.drop-overlay[hidden] { display: none; }
.installed-info {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  margin-bottom: 14px;
  padding: 11px 14px;
  border-left: 2px solid var(--purple);
  background: rgba(155, 107, 255, 0.05);
  color: var(--muted);
}
.installed-info .icon { width: 15px; height: 15px; color: var(--purple); margin-top: 2px; }
.installed-info p { font-size: 12.5px; line-height: 1.45; }
.installed-list { display: flex; flex-direction: column; gap: 8px; }
.installed-card {
  display: grid;
  grid-template-columns: 66px minmax(0, 1fr) auto;
  align-items: center;
  gap: 14px;
  padding: 11px 14px;
  border: 1px solid var(--line);
  background: rgba(13, 9, 22, 0.88);
  transition: border-color 0.18s, background 0.18s;
}
.installed-card:hover { border-color: var(--line-bright); }
.installed-card.is-active { border-left: 2px solid var(--mod-accent); background: linear-gradient(90deg, rgba(255, 51, 85, 0.04), rgba(13, 9, 22, 0.9) 32%); }
.installed-thumb {
  width: 66px; height: 44px;
  display: grid; place-items: center;
  border: 1px solid var(--line);
  background:
    linear-gradient(135deg, color-mix(in srgb, var(--card-accent, #ff3355) 26%, #0b0813), #0b0813 70%);
  color: var(--card-accent, var(--red));
  overflow: hidden;
}
.installed-thumb .icon { width: 20px; height: 20px; }
.installed-thumb img { width: 100%; height: 100%; object-fit: cover; }
.installed-main { min-width: 0; }
.installed-name { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; font-size: 15px; font-weight: 700; line-height: 1.2; }
.installed-name .status-chip {
  padding: 2px 5px;
  border: 1px solid rgba(109, 255, 168, 0.35);
  color: var(--green);
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 400;
  letter-spacing: 0.06em;
}
.installed-sub {
  display: flex;
  flex-wrap: wrap;
  gap: 5px 10px;
  margin-top: 4px;
  color: var(--muted-dim);
  font-family: var(--font-mono);
  font-size: 12px;
}
.installed-sub span { display: inline-flex; align-items: center; gap: 4px; }
.installed-sub .icon { width: 9px; height: 9px; }
.installed-kind { color: var(--purple); }
.installed-actions { display: flex; align-items: center; gap: 7px; }
.install-toggle {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  height: 30px;
  padding: 0 10px;
  border: 1px solid var(--line);
  background: #0b0813;
  color: var(--muted);
  font-family: var(--font-mono);
  font-size: 12px;
  letter-spacing: 0.04em;
}
.install-toggle i { width: 7px; height: 7px; background: var(--muted-dim); }
.install-toggle.is-active { border-color: rgba(109, 255, 168, 0.35); color: var(--green); }
.install-toggle.is-active i { background: var(--green); box-shadow: 0 0 7px var(--green); }
.icon-action {
  width: 30px; height: 30px;
  display: grid; place-items: center;
  border: 1px solid var(--line);
  background: #0b0813;
  color: var(--muted);
}
.icon-action .icon { width: 12px; height: 12px; }
.icon-action:hover { color: var(--text); border-color: var(--line-bright); }
.icon-action.danger:hover { color: var(--red); border-color: rgba(255, 51, 85, 0.5); }

/* ══════════════ Modal ══════════════ */

.modal-layer {
  position: fixed;
  inset: 0;
  z-index: 120;
  display: grid;
  place-items: center;
  padding: clamp(12px, 4vw, 42px);
}
.modal-layer[hidden] { display: none; }
.modal-backdrop {
  position: absolute;
  inset: 0;
  background: rgba(3, 2, 7, 0.78);
  backdrop-filter: blur(7px);
  animation: fade-in 0.2s ease;
}
.modal {
  position: relative;
  z-index: 1;
  width: min(880px, 100%);
  max-height: min(90dvh, 900px);
  overflow: auto;
  border: 1px solid var(--line-bright);
  background:
    linear-gradient(160deg, rgba(255, 51, 85, 0.04), transparent 28%),
    #0e0a18;
  box-shadow: var(--shadow), 0 0 0 6px rgba(5, 4, 9, 0.45);
  animation: modal-in 0.22s var(--ease-snap);
  scrollbar-width: thin;
}
@keyframes modal-in { from { opacity: 0; transform: translateY(14px) scale(0.985); } to { opacity: 1; transform: none; } }
@keyframes fade-in { from { opacity: 0; } to { opacity: 1; } }
.modal-close {
  position: absolute;
  right: 10px; top: 10px;
  z-index: 4;
  background: rgba(5, 4, 9, 0.8);
}
.modal-body { min-height: 150px; }
.modal-hero {
  position: relative;
  height: clamp(160px, 28vw, 280px);
  background: #08060f;
  overflow: hidden;
}
.modal-hero img { width: 100%; height: 100%; object-fit: cover; filter: saturate(0.85); }
.modal-hero::after { content: ''; position: absolute; inset: 0; background: linear-gradient(180deg, transparent 30%, #0e0a18); }
.modal-hero .thumb-fallback { position: absolute; inset: 0; }
.modal-head { position: relative; z-index: 1; margin-top: -46px; padding: 0 clamp(18px, 3vw, 30px) 18px; }
.modal-kicker { display: flex; align-items: center; gap: 8px; margin-bottom: 7px; color: var(--red); font-family: var(--font-mono); font-size: 12px; letter-spacing: 0.12em; }
.modal-kicker .icon { width: 11px; height: 11px; }
.modal-head h2 { font-size: clamp(22px, 3vw, 34px); line-height: 1.08; margin-bottom: 8px; max-width: 90%; }
.modal-meta { display: flex; flex-wrap: wrap; align-items: center; gap: 7px 14px; color: var(--muted); font-family: var(--font-mono); font-size: 13px; }
.modal-meta span { display: inline-flex; align-items: center; gap: 5px; }
.modal-meta .icon { width: 11px; height: 11px; }
.modal-content { padding: 0 clamp(18px, 3vw, 30px) 26px; }
.modal-desc {
  margin: 16px 0;
  padding: 14px 16px;
  border-left: 2px solid var(--line-bright);
  background: rgba(255, 255, 255, 0.018);
  color: var(--text-soft);
  font-size: 13.5px;
  line-height: 1.58;
  white-space: pre-line;
  max-height: 220px;
  overflow: auto;
}
.modal-section-title {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 20px 0 9px;
  color: var(--muted);
  font-family: var(--font-mono);
  font-size: 13px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}
.modal-section-title::after { content: ''; flex: 1; height: 1px; background: var(--line-soft); }
.file-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 10px 14px;
  align-items: center;
  padding: 10px 12px;
  border: 1px solid var(--line-soft);
  background: rgba(9, 6, 15, 0.6);
  margin-bottom: 6px;
}
.file-name { font-size: 13px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.file-meta { display: flex; flex-wrap: wrap; gap: 7px 12px; margin-top: 3px; color: var(--muted-dim); font-family: var(--font-mono); font-size: 11.5px; }
.file-meta .ok { color: var(--green); }
.file-actions { display: flex; align-items: center; gap: 6px; }
.file-actions .pixel-button { min-height: 30px; font-size: 10px; }
.progress-line {
  grid-column: 1 / -1;
  height: 4px;
  background: #21172f;
  overflow: hidden;
}
.progress-line i { display: block; height: 100%; width: 0; background: linear-gradient(90deg, var(--red), var(--gold)); transition: width 0.15s; }
.modal-actions { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; margin-top: 18px; }
.modal-actions .modal-spacer { flex: 1; }
.modal-hint { color: var(--muted-dim); font-size: 11.5px; line-height: 1.45; margin-top: 12px; }
.modal-loading { display: grid; place-items: center; gap: 12px; min-height: 320px; color: var(--muted); font-family: var(--font-mono); }
.modal-loading .loader-heart { width: 28px; height: 28px; color: var(--red); animation: heart-float 1s steps(2, end) infinite; }
.modal-error { padding: 40px 24px; text-align: center; color: var(--muted); }
.modal-error strong { display: block; margin-bottom: 6px; color: var(--text); }
.confirm-box { padding: 32px clamp(20px, 4vw, 40px); text-align: center; }
.confirm-icon { width: 58px; height: 58px; margin: 0 auto 16px; display: grid; place-items: center; border: 1px solid rgba(255, 51, 85, 0.35); background: rgba(255, 51, 85, 0.07); color: var(--red); }
.confirm-icon .icon { width: 24px; height: 24px; }
.confirm-box h2 { font-size: 23px; margin-bottom: 8px; }
.confirm-box p { max-width: 460px; margin: 0 auto 20px; color: var(--muted); font-size: 13.5px; line-height: 1.55; }
.confirm-actions { display: flex; justify-content: center; gap: 8px; flex-wrap: wrap; }

.modal-screens { display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px; margin: 14px 0; }
.modal-screens img { width: 100%; aspect-ratio: 16/9; object-fit: cover; border: 1px solid var(--line-soft); filter: saturate(0.8); cursor: zoom-in; }
.modal-screens img:hover { filter: saturate(1); }

/* Toasts */

.toast-region {
  position: fixed;
  right: clamp(12px, 3vw, 30px);
  bottom: clamp(46px, 6vw, 70px);
  z-index: 200;
  display: flex;
  flex-direction: column;
  gap: 8px;
  width: min(360px, calc(100vw - 24px));
  pointer-events: none;
}
.toast {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 11px 13px;
  border: 1px solid var(--line-bright);
  border-left: 3px solid var(--red);
  background: rgba(12, 8, 20, 0.97);
  box-shadow: 5px 5px 0 rgba(4, 3, 9, 0.55);
  color: var(--text-soft);
  font-size: 12.5px;
  line-height: 1.4;
  pointer-events: auto;
  animation: toast-in 0.25s var(--ease-snap);
}
.toast.is-success { border-left-color: var(--green); }
.toast.is-warning { border-left-color: var(--orange); }
.toast.is-error { border-left-color: var(--red); }
.toast .icon { width: 14px; height: 14px; margin-top: 1px; color: var(--red); }
.toast.is-success .icon { color: var(--green); }
.toast.is-warning .icon { color: var(--orange); }
.toast strong { display: block; margin-bottom: 2px; color: var(--text); font-size: 12px; }
.toast span { color: var(--muted); }
.toast.is-out { animation: toast-out 0.22s ease forwards; }
@keyframes toast-in { from { opacity: 0; transform: translateX(16px); } to { opacity: 1; transform: none; } }
@keyframes toast-out { to { opacity: 0; transform: translateX(20px); } }

/* ══════════════ GAME ══════════════ */

body.is-playing .topbar,
body.is-playing .statusbar { display: none; }
body.is-playing .main-stage { height: 100dvh; }
.view-game {
  height: 100dvh;
  padding: 0;
  background:
    radial-gradient(ellipse 55% 45% at 50% 0%, rgba(72, 32, 96, 0.2), transparent 60%),
    #06050b;
  animation: none;
}
.game-wrap {
  height: 100%;
  width: min(1180px, 100%);
  margin: 0 auto;
  padding: max(10px, env(safe-area-inset-top)) clamp(10px, 2.5vw, 26px) max(8px, env(safe-area-inset-bottom));
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.game-topline { display: flex; align-items: center; gap: 12px; min-height: 50px; }
.game-topline .back-button { flex: none; }
.game-hud {
  flex: 1;
  display: flex;
  align-items: stretch;
  justify-content: center;
  min-width: 0;
  border: 1px solid var(--line);
  background: rgba(10, 7, 17, 0.78);
}
.hud-cell {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 2px;
  min-width: 110px;
  padding: 7px 13px;
  border-right: 1px solid var(--line-soft);
}
.hud-cell:last-child { border-right: 0; }
.hud-label { color: var(--muted-dim); font-size: 8px; font-weight: 600; letter-spacing: 0.16em; }
.hud-cell strong { font-family: var(--font-mono); font-size: 17px; font-weight: 400; letter-spacing: 0.04em; line-height: 1; white-space: nowrap; }
.hud-cell strong small { color: var(--muted-dim); font-size: 12px; }
.hud-hp { min-width: 130px; }
.hp-track { width: 100%; height: 3px; margin-top: 3px; background: #342038; }
.hp-track i { display: block; height: 100%; width: 100%; background: var(--gold); box-shadow: 0 0 7px rgba(255, 215, 94, 0.5); transition: width 0.25s; }
.hud-active-mod { max-width: 190px; }
.hud-active-mod strong { color: var(--mod-accent, var(--gold)); overflow: hidden; text-overflow: ellipsis; }
.pause-btn { width: 42px; height: 42px; flex: none; }

.game-stage { flex: 1; min-height: 0; display: flex; align-items: center; justify-content: center; }
.game-bezel {
  position: relative;
  width: min(100%, calc((100dvh - 260px) * 1.5), 1040px);
  aspect-ratio: 3 / 2;
  padding: 6px;
  border: 1px solid #3c2b55;
  background: #05040a;
  box-shadow: 0 0 0 1px #0d0914, 0 20px 70px rgba(0, 0, 0, 0.6), 0 0 80px rgba(155, 107, 255, 0.05);
}
#game-canvas {
  width: 100%;
  height: 100%;
  display: block;
  image-rendering: pixelated;
  image-rendering: crisp-edges;
  background: #0b0813;
  touch-action: none;
}
body.no-pixel-filter #game-canvas { image-rendering: auto; }
.canvas-scan {
  position: absolute;
  inset: 6px;
  pointer-events: none;
  background: repeating-linear-gradient(to bottom, transparent 0 2px, rgba(0, 0, 0, 0.2) 3px 4px);
  opacity: 0.45;
  mix-blend-mode: multiply;
}
body.no-scanlines .canvas-scan { display: none; }
.game-toast {
  position: absolute;
  top: 18px;
  left: 50%;
  z-index: 3;
  transform: translateX(-50%);
  padding: 6px 12px;
  border: 1px solid var(--line-bright);
  background: rgba(7, 5, 12, 0.92);
  color: var(--gold);
  font-family: var(--font-mono);
  font-size: 14px;
  letter-spacing: 0.06em;
  pointer-events: none;
  animation: toast-in 0.2s ease;
}
.game-toast[hidden] { display: none; }

.game-loading {
  position: absolute;
  inset: 6px;
  z-index: 8;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 11px;
  background: #08060f;
  transition: opacity 0.4s ease, visibility 0.4s;
}
.game-loading.is-done { opacity: 0; visibility: hidden; }
.loading-heart { color: var(--red); animation: heart-float 1s steps(2, end) infinite; }
.loading-heart .icon { width: 30px; height: 30px; filter: drop-shadow(0 0 10px var(--red)); }
.loading-title { font-family: var(--font-pixel); font-size: 13px; letter-spacing: 0.06em; }
html[data-lang='ru'] .loading-title { font-family: var(--font-ui); font-size: 18px; font-weight: 700; }
.loading-bar { width: min(260px, 60%); height: 4px; background: #24172f; }
.loading-bar i { display: block; width: 0; height: 100%; background: linear-gradient(90deg, var(--red), var(--gold)); transition: width 0.25s; }
.loading-log { color: var(--muted-dim); font-family: var(--font-mono); font-size: 13px; letter-spacing: 0.14em; }

.battle-banner {
  position: absolute;
  top: 18px;
  left: 50%;
  z-index: 4;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
  width: min(360px, 72%);
  padding: 8px 14px 9px;
  border: 1px solid rgba(255, 51, 85, 0.5);
  background: rgba(7, 4, 11, 0.9);
  text-align: center;
  pointer-events: none;
}
.battle-banner[hidden] { display: none; }
.battle-alert { color: var(--red); font-family: var(--font-mono); font-size: 11px; letter-spacing: 0.24em; }
.battle-banner strong { font-size: 14px; letter-spacing: 0.12em; }
.battle-timer-wrap { width: 100%; height: 3px; margin-top: 3px; background: #311b34; }
.battle-timer-wrap i { display: block; height: 100%; width: 100%; background: var(--gold); transition: width 0.1s linear; }
.battle-timer { color: var(--muted); font-family: var(--font-mono); font-size: 11px; }

.dialog-box {
  position: absolute;
  left: 16px; right: 16px; bottom: 14px;
  z-index: 5;
  min-height: 84px;
  padding: 12px 16px 12px;
  border: 2px solid var(--text);
  background: rgba(5, 4, 9, 0.93);
  box-shadow: 0 0 0 3px rgba(5, 4, 9, 0.9), 0 8px 30px rgba(0, 0, 0, 0.5);
}
.dialog-box[hidden] { display: none; }
.dialog-name {
  position: absolute;
  top: -12px; left: 14px;
  padding: 2px 8px;
  background: var(--red);
  color: #fff;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.12em;
  line-height: 1.4;
}
.dialog-text {
  min-height: 40px;
  padding-right: 46px;
  color: #fff;
  font-family: var(--font-mono);
  font-size: clamp(16px, 2.2vw, 23px);
  line-height: 1.2;
  letter-spacing: 0.01em;
}
html[data-lang='ru'] .dialog-text { font-family: var(--font-ui); font-size: clamp(13px, 1.6vw, 16px); line-height: 1.45; }
.dialog-next {
  position: absolute;
  right: 8px; bottom: 6px;
  display: flex;
  align-items: center;
  gap: 5px;
  color: var(--muted);
  font-family: var(--font-mono);
  font-size: 12px;
  animation: blink 1s steps(2, end) infinite;
}
.dialog-next kbd { border-color: var(--red); color: var(--red); }

.game-prompt {
  position: absolute;
  left: 50%; bottom: 16px;
  z-index: 3;
  transform: translateX(-50%);
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 5px 10px;
  border: 1px solid var(--line-bright);
  background: rgba(7, 5, 12, 0.9);
  color: var(--text-soft);
  font-family: var(--font-mono);
  font-size: 13px;
  white-space: nowrap;
}
.game-prompt[hidden] { display: none; }
.game-prompt kbd { border-color: var(--gold); color: var(--gold); }

.game-controls {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 14px;
  padding: 4px 4px 0;
}
.control-hint { display: flex; flex-direction: column; gap: 2px; color: var(--muted-dim); font-family: var(--font-mono); font-size: 12px; letter-spacing: 0.04em; }
.control-hint.center { align-items: center; text-align: center; }
.control-hint.right { align-items: flex-end; text-align: right; }
.dpad {
  display: grid;
  grid-template-columns: repeat(3, 46px);
  grid-template-rows: repeat(3, 46px);
  gap: 2px;
  justify-self: center;
  touch-action: none;
  user-select: none;
  -webkit-user-select: none;
}
.dpad-btn {
  display: grid;
  place-items: center;
  border: 1px solid #3e2c58;
  background: linear-gradient(180deg, #191126, #0e0a17);
  color: var(--text-soft);
  box-shadow: 0 4px 0 #040308;
  padding: 0;
  touch-action: none;
  transition: background 0.06s, color 0.06s, transform 0.06s, box-shadow 0.06s;
}
.dpad-btn .icon { width: 14px; height: 14px; }
.dpad-up { grid-area: 1 / 2; }
.dpad-up .icon { transform: rotate(-90deg); }
.dpad-left { grid-area: 2 / 1; }
.dpad-left .icon { transform: rotate(180deg); }
.dpad-right { grid-area: 2 / 3; }
.dpad-down { grid-area: 3 / 2; }
.dpad-down .icon { transform: rotate(90deg); }
.dpad-center { grid-area: 2 / 2; display: grid; place-items: center; border: 1px solid #241a34; background: #0b0813; }
.dpad-center i { width: 12px; height: 12px; border: 1px solid rgba(255, 51, 85, 0.5); background: rgba(255, 51, 85, 0.12); box-shadow: 0 0 8px rgba(255, 51, 85, 0.18); }
.dpad-btn.is-pressed { background: var(--red); color: #fff; border-color: var(--red-hot); transform: translateY(3px); box-shadow: 0 1px 0 #040308; }
.game-actions { display: flex; align-items: center; gap: 12px; justify-self: end; }
.round-btn {
  width: 64px; height: 64px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;
  border: 1px solid #49345f;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, #231733, #0e0a17);
  color: var(--text-soft);
  box-shadow: 0 5px 0 #040308, inset 0 0 0 4px rgba(255, 255, 255, 0.025);
  touch-action: none;
  user-select: none;
  transition: transform 0.07s, box-shadow 0.07s, background 0.07s;
}
.round-btn b { font-family: var(--font-pixel); font-size: 17px; line-height: 1; }
html[data-lang='ru'] .round-btn b { font-family: var(--font-ui); font-size: 21px; }
.round-btn span { font-family: var(--font-mono); font-size: 9px; letter-spacing: 0.04em; color: var(--muted); }
.round-a { border-color: rgba(255, 51, 85, 0.65); background: radial-gradient(circle at 35% 30%, #431426, #180a10); color: #ffd8df; }
.round-a b { color: var(--red-hot); }
.round-btn.is-pressed { transform: translateY(4px) scale(0.97); box-shadow: 0 1px 0 #040308; }
.round-a.is-pressed { background: var(--red); color: #fff; }
.round-a.is-pressed b { color: #fff; }
.round-a.is-pressed span { color: rgba(255, 255, 255, 0.7); }

.game-underbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 0 6px;
  color: var(--muted-dim);
  font-family: var(--font-mono);
  font-size: 12.5px;
  letter-spacing: 0.05em;
}
.underbar-status { display: inline-flex; align-items: center; gap: 7px; color: var(--muted); }
.underbar-objective { flex: 1; text-align: center; color: var(--muted); }
.underbar-mod { padding: 2px 7px; border: 1px solid var(--line); color: var(--mod-accent, var(--muted)); white-space: nowrap; max-width: 220px; overflow: hidden; text-overflow: ellipsis; }

body.lefty .game-controls { grid-template-columns: 1fr auto 1fr; }
body.lefty .dpad { order: 3; }
body.lefty .game-actions { order: 1; justify-self: start; }
body.lefty .control-hint.left { order: 2; text-align: right; align-items: flex-end; }
body.lefty .control-hint.right { order: 0; text-align: left; align-items: flex-start; }

/* Game overlays */

.game-overlay {
  position: fixed;
  inset: 0;
  z-index: 70;
  display: grid;
  place-items: center;
  padding: 20px;
  background: rgba(4, 3, 8, 0.8);
  backdrop-filter: blur(6px);
  animation: fade-in 0.2s ease;
}
.game-overlay[hidden] { display: none; }
.overlay-panel {
  width: min(440px, 100%);
  padding: 28px;
  border: 1px solid var(--line-bright);
  background:
    linear-gradient(160deg, rgba(255, 51, 85, 0.06), transparent 30%),
    #0f0a19;
  box-shadow: 0 30px 80px rgba(0, 0, 0, 0.65), 0 0 0 5px rgba(5, 4, 9, 0.4);
  text-align: center;
  animation: modal-in 0.24s var(--ease-snap);
}
.overlay-kicker {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  margin-bottom: 9px;
  color: var(--red);
  font-family: var(--font-mono);
  font-size: 12px;
  letter-spacing: 0.14em;
}
.overlay-kicker .icon { width: 11px; height: 11px; }
.overlay-panel h3 { font-family: var(--font-pixel); font-size: clamp(19px, 3vw, 27px); line-height: 1.2; margin-bottom: 10px; }
html[data-lang='ru'] .overlay-panel h3 { font-family: var(--font-ui); font-weight: 700; letter-spacing: 0.03em; font-size: clamp(23px, 3.4vw, 31px); }
.overlay-panel > p { color: var(--muted); font-size: 13px; line-height: 1.5; }
.overlay-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1px;
  margin: 18px 0;
  border: 1px solid var(--line);
  background: var(--line);
}
.overlay-stats span { display: flex; flex-direction: column; gap: 3px; padding: 10px 6px; background: #0b0812; }
.overlay-stats b { font-family: var(--font-mono); font-size: 20px; font-weight: 400; color: var(--text); line-height: 1; }
.overlay-stats small { color: var(--muted-dim); font-family: var(--font-mono); font-size: 10px; letter-spacing: 0.06em; }
.overlay-actions { display: flex; flex-direction: column; gap: 7px; margin-top: 16px; }
.overlay-actions .pixel-button { width: 100%; }
.overlay-note { margin-top: 14px; color: var(--muted-dim); font-size: 11px; }
.complete-panel { border-color: rgba(255, 215, 94, 0.4); }
.complete-panel .overlay-kicker { color: var(--gold); }
.complete-copy { margin-bottom: 4px; }
.complete-stats { margin-top: 16px; }
.death-panel { border-color: rgba(255, 51, 85, 0.4); }
.death-heart { position: relative; width: 54px; height: 54px; margin: 0 auto 14px; display: grid; place-items: center; color: var(--red); }
.death-heart .icon { width: 40px; height: 40px; filter: drop-shadow(0 0 12px var(--red)); }
.death-heart i { position: absolute; inset: 0; border: 2px solid var(--red); transform: rotate(45deg); opacity: 0.2; }
.death-panel h3 { color: var(--red-hot); }

