/* SOUL LINK — original WebAudio chiptune and UI effects. */
(function () {
  'use strict';

  const BPM = 86;
  const STEP = 60 / BPM / 2;

  /* An original little loop. No borrowed melodies. */
  const BASS = [
    38, 0, 0, 0, 38, 0, 45, 0, 41, 0, 0, 0, 41, 0, 48, 0,
    36, 0, 0, 0, 36, 0, 43, 0, 41, 0, 0, 0, 45, 0, 43, 0
  ];
  const ARP = [
    62, 65, 69, 65, 62, 69, 65, 69, 65, 69, 72, 69, 65, 72, 69, 72,
    60, 64, 67, 64, 60, 67, 64, 67, 65, 69, 72, 69, 65, 72, 69, 65
  ];
  const PAD = [
    50, 0, 0, 0, 0, 0, 0, 0, 53, 0, 0, 0, 0, 0, 0, 0,
    48, 0, 0, 0, 0, 0, 0, 0, 53, 0, 0, 0, 0, 0, 0, 0
  ];

  function midi(n) {
    return 440 * Math.pow(2, (n - 69) / 12);
  }

  class Engine {
    constructor() {
      this.ctx = null;
      this.master = null;
      this.musicGain = null;
      this.sfxGain = null;
      this.comp = null;
      this.volumes = { master: 72, music: 35, sfx: 68 };
      this.muted = false;
      this.playing = false;
      this.timer = null;
      this.step = 0;
      this.nextTime = 0;
      this.unlocked = false;
      this.musicWanted = true;
      this.noiseBuffer = null;
    }

    init() {
      if (this.ctx) {
        if (this.ctx.state === 'suspended') this.ctx.resume().catch(function () {});
        return this.ctx;
      }
      const Ctx = window.AudioContext || window.webkitAudioContext;
      if (!Ctx) return null;
      try {
        this.ctx = new Ctx();
        this.comp = this.ctx.createDynamicsCompressor();
        this.comp.threshold.value = -18;
        this.comp.knee.value = 18;
        this.comp.ratio.value = 5;
        this.comp.attack.value = 0.002;
        this.comp.release.value = 0.22;
        this.master = this.ctx.createGain();
        this.musicGain = this.ctx.createGain();
        this.sfxGain = this.ctx.createGain();
        this.musicGain.connect(this.comp);
        this.sfxGain.connect(this.comp);
        this.comp.connect(this.master);
        this.master.connect(this.ctx.destination);
        this.applyVolumes();
        this.makeNoise();
        this.unlocked = true;
      } catch (_) {
        this.ctx = null;
      }
      return this.ctx;
    }

    makeNoise() {
      if (!this.ctx) return;
      const length = Math.floor(this.ctx.sampleRate * 0.25);
      const buffer = this.ctx.createBuffer(1, length, this.ctx.sampleRate);
      const data = buffer.getChannelData(0);
      for (let i = 0; i < length; i++) data[i] = (Math.random() * 2 - 1) * (1 - i / length);
      this.noiseBuffer = buffer;
    }

    applyVolumes() {
      if (!this.ctx) return;
      const now = this.ctx.currentTime;
      const master = this.muted ? 0 : (this.volumes.master / 100) * 0.85;
      this.master.gain.cancelScheduledValues(now);
      this.master.gain.setTargetAtTime(master, now, 0.05);
      this.musicGain.gain.setTargetAtTime((this.volumes.music / 100) * 0.32, now, 0.05);
      this.sfxGain.gain.setTargetAtTime((this.volumes.sfx / 100) * 0.55, now, 0.05);
    }

    setVolumes(next) {
      this.volumes.master = next.master != null ? next.master : this.volumes.master;
      this.volumes.music = next.music != null ? next.music : this.volumes.music;
      this.volumes.sfx = next.sfx != null ? next.sfx : this.volumes.sfx;
      this.muted = !!next.muted;
      this.applyVolumes();
      if (!this.muted && this.musicWanted) this.startMusic();
      if (this.muted) this.stopMusic(true);
    }

    setMuted(muted) {
      this.muted = !!muted;
      this.applyVolumes();
      if (!this.muted && this.musicWanted) this.startMusic();
      else this.stopMusic(true);
    }

    startMusic() {
      this.musicWanted = true;
      if (!this.ctx || this.muted) return;
      if (this.playing) return;
      if (this.ctx.state === 'suspended') this.ctx.resume().catch(function () {});
      this.playing = true;
      this.step = 0;
      this.nextTime = this.ctx.currentTime + 0.06;
      const self = this;
      this.timer = window.setInterval(function () { self.schedule(); }, 70);
      this.schedule();
    }

    stopMusic(immediate) {
      this.musicWanted = false;
      if (!this.playing) return;
      this.playing = false;
      if (this.timer) {
        clearInterval(this.timer);
        this.timer = null;
      }
      if (immediate) {
        try { this.musicGain.gain.setTargetAtTime(0, this.ctx.currentTime, 0.03); } catch (_) {}
        const self = this;
        window.setTimeout(function () {
          if (!self.playing && self.musicGain) self.musicGain.gain.setTargetAtTime(0.32 * (self.volumes.music / 100), self.ctx.currentTime, 0.1);
        }, 220);
      }
    }

    schedule() {
      if (!this.ctx || !this.playing) return;
      const now = this.ctx.currentTime;
      while (this.nextTime < now + 0.18) {
        this.playStep(this.step, this.nextTime);
        this.step = (this.step + 1) % 32;
        this.nextTime += STEP;
      }
    }

    playStep(step, time) {
      const bassNote = BASS[step];
      const arpNote = ARP[step];
      const padNote = PAD[step];
      if (bassNote) this.note(midi(bassNote), time, STEP * 1.7, 'triangle', 0.34, this.musicGain);
      if (arpNote) this.note(midi(arpNote), time + 0.008, STEP * 0.78, 'square', 0.075, this.musicGain);
      if (padNote) this.note(midi(padNote), time, STEP * 3.5, 'sine', 0.11, this.musicGain);
      if (step % 8 === 4) this.note(midi(86), time, 0.04, 'square', 0.035, this.musicGain);
    }

    note(freq, when, duration, type, peak, destination) {
      if (!this.ctx || !destination) return;
      const osc = this.ctx.createOscillator();
      const gain = this.ctx.createGain();
      osc.type = type;
      osc.frequency.setValueAtTime(freq, when);
      gain.gain.setValueAtTime(0.0001, when);
      gain.gain.exponentialRampToValueAtTime(Math.max(0.0002, peak), when + 0.008);
      gain.gain.exponentialRampToValueAtTime(0.0001, when + duration);
      osc.connect(gain);
      gain.connect(destination);
      osc.start(when);
      osc.stop(when + duration + 0.03);
    }

    slide(freq, to, when, duration, type, peak, destination) {
      if (!this.ctx || !destination) return;
      const osc = this.ctx.createOscillator();
      const gain = this.ctx.createGain();
      osc.type = type;
      osc.frequency.setValueAtTime(freq, when);
      osc.frequency.exponentialRampToValueAtTime(Math.max(20, to), when + duration);
      gain.gain.setValueAtTime(0.0001, when);
      gain.gain.exponentialRampToValueAtTime(Math.max(0.0002, peak), when + 0.006);
      gain.gain.exponentialRampToValueAtTime(0.0001, when + duration);
      osc.connect(gain);
      gain.connect(destination);
      osc.start(when);
      osc.stop(when + duration + 0.03);
    }

    noise(when, duration, peak, destination, highpass) {
      if (!this.ctx || !this.noiseBuffer || !destination) return;
      const src = this.ctx.createBufferSource();
      src.buffer = this.noiseBuffer;
      const filter = this.ctx.createBiquadFilter();
      filter.type = 'highpass';
      filter.frequency.value = highpass || 700;
      const gain = this.ctx.createGain();
      gain.gain.setValueAtTime(peak, when);
      gain.gain.exponentialRampToValueAtTime(0.0001, when + duration);
      src.connect(filter);
      filter.connect(gain);
      gain.connect(destination);
      src.start(when);
      src.stop(when + duration);
    }

    sfx(name) {
      if (!this.ctx || this.muted) return;
      const t = this.ctx.currentTime + 0.005;
      const out = this.sfxGain;
      switch (name) {
        case 'move':
          this.slide(320, 220, t, 0.06, 'square', 0.09, out);
          break;
        case 'confirm':
          this.slide(440, 660, t, 0.07, 'square', 0.12, out);
          this.slide(660, 880, t + 0.06, 0.08, 'square', 0.09, out);
          break;
        case 'back':
          this.slide(360, 180, t, 0.11, 'square', 0.1, out);
          break;
        case 'pickup':
          this.slide(660, 990, t, 0.09, 'triangle', 0.15, out);
          this.slide(990, 1320, t + 0.08, 0.13, 'triangle', 0.12, out);
          this.slide(1320, 1760, t + 0.16, 0.11, 'triangle', 0.08, out);
          break;
        case 'heal':
          this.slide(520, 780, t, 0.18, 'sine', 0.14, out);
          this.slide(780, 1040, t + 0.12, 0.2, 'sine', 0.09, out);
          break;
        case 'hurt':
          this.slide(150, 55, t, 0.2, 'sawtooth', 0.2, out);
          this.noise(t, 0.12, 0.12, out, 400);
          break;
        case 'battle':
          this.slide(90, 290, t, 0.28, 'sawtooth', 0.12, out);
          this.noise(t, 0.3, 0.04, out, 1800);
          break;
        case 'gate':
          this.slide(392, 784, t, 0.5, 'triangle', 0.13, out);
          this.slide(523, 1046, t + 0.1, 0.55, 'sine', 0.08, out);
          break;
        case 'error':
          this.slide(180, 120, t, 0.16, 'square', 0.14, out);
          break;
        case 'install':
          this.slide(523, 784, t, 0.12, 'square', 0.1, out);
          this.slide(784, 1046, t + 0.1, 0.16, 'square', 0.08, out);
          break;
        case 'delete':
          this.slide(260, 90, t, 0.2, 'square', 0.12, out);
          break;
        default:
          this.slide(440, 440, t, 0.04, 'square', 0.06, out);
      }
    }
  }

  const engine = new Engine();

  window.SL = window.SL || {};
  SL.audio = {
    engine: engine,
    init: function () { return engine.init(); },
    startMusic: function () { engine.init(); engine.startMusic(); },
    stopMusic: function (immediate) { engine.stopMusic(immediate); },
    setVolumes: function (volumes) { engine.init(); engine.setVolumes(volumes); },
    setMuted: function (muted) { engine.init(); engine.setMuted(muted); },
    sfx: function (name) { engine.init(); engine.sfx(name); },
    unlock: function () {
      engine.init();
      if (!engine.playing && !engine.muted) engine.startMusic();
    },
    get isPlaying() { return engine.playing; }
  };
})();

/* SOUL LINK — settings, local mod library, IndexedDB blobs and theme profile. */
(function () {
  'use strict';

  const SETTINGS_KEY = 'soullink.settings.v1';
  const MODS_KEY = 'soullink.mods.v1';
  const DB_NAME = 'soullink.files.v1';
  const DB_STORE = 'files';

  const memoryFiles = new Map();
  let dbPromise = null;
  let dbBroken = false;

  const defaults = (window.SL && SL.data && SL.data.DEFAULT_SETTINGS) || {
    master: 72, music: 35, sfx: 68, muted: false, scanlines: true,
    shake: true, reduceMotion: false, pixelPerfect: true,
    touchAlways: true, lefty: false, haptics: true
  };

  const palettes = (window.SL && SL.data && SL.data.PALETTES) || [];

  function safeParse(value, fallback) {
    if (!value) return fallback;
    try { return JSON.parse(value); } catch (_) { return fallback; }
  }

  function loadSettings() {
    let saved = {};
    try { saved = safeParse(localStorage.getItem(SETTINGS_KEY), {}); } catch (_) {}
    const merged = Object.assign({}, defaults, saved && typeof saved === 'object' ? saved : {});
    ['master', 'music', 'sfx'].forEach(function (key) {
      const n = Number(merged[key]);
      merged[key] = Number.isFinite(n) ? Math.max(0, Math.min(100, Math.round(n))) : defaults[key];
    });
    ['muted', 'scanlines', 'shake', 'reduceMotion', 'pixelPerfect', 'touchAlways', 'lefty', 'haptics'].forEach(function (key) {
      merged[key] = !!merged[key];
    });
    return merged;
  }

  let settings = loadSettings();

  function saveSettings(patch) {
    settings = Object.assign({}, settings, patch || {});
    try { localStorage.setItem(SETTINGS_KEY, JSON.stringify(settings)); } catch (_) {}
    applySettingsClasses();
    document.dispatchEvent(new CustomEvent('soullink:settings', { detail: { settings: settings } }));
    return settings;
  }

  function applySettingsClasses() {
    const body = document.body;
    if (!body) return;
    body.classList.toggle('no-scanlines', !settings.scanlines);
    body.classList.toggle('reduce-motion', settings.reduceMotion);
    body.classList.toggle('no-pixel-filter', !settings.pixelPerfect);
    body.classList.toggle('is-muted', settings.muted);
    body.classList.toggle('lefty', settings.lefty);
    body.classList.toggle('show-touch-always', settings.touchAlways);
    document.documentElement.style.setProperty('--settings-master', String(settings.master));
  }

  /* ── IndexedDB ───────────────────────────────────────────── */

  function openDb() {
    if (dbBroken) return Promise.resolve(null);
    if (dbPromise) return dbPromise;
    dbPromise = new Promise(function (resolve) {
      try {
        if (!window.indexedDB) return resolve(null);
        const req = indexedDB.open(DB_NAME, 1);
        req.onupgradeneeded = function () {
          const db = req.result;
          if (!db.objectStoreNames.contains(DB_STORE)) db.createObjectStore(DB_STORE);
        };
        req.onsuccess = function () { resolve(req.result); };
        req.onerror = function () { dbBroken = true; resolve(null); };
        req.onblocked = function () { resolve(null); };
      } catch (_) {
        dbBroken = true;
        resolve(null);
      }
    });
    return dbPromise;
  }

  async function putFile(id, blob) {
    const db = await openDb();
    if (!db) {
      memoryFiles.set(id, blob);
      return false;
    }
    return new Promise(function (resolve, reject) {
      try {
        const tx = db.transaction(DB_STORE, 'readwrite');
        tx.objectStore(DB_STORE).put(blob, id);
        tx.oncomplete = function () { resolve(true); };
        tx.onerror = function () { reject(tx.error || new Error('indexeddb write failed')); };
        tx.onabort = function () { reject(tx.error || new Error('indexeddb write aborted')); };
      } catch (err) {
        reject(err);
      }
    });
  }

  async function getFile(id) {
    if (!id) return null;
    const db = await openDb();
    if (!db) return memoryFiles.get(id) || null;
    return new Promise(function (resolve, reject) {
      try {
        const tx = db.transaction(DB_STORE, 'readonly');
        const req = tx.objectStore(DB_STORE).get(id);
        req.onsuccess = function () { resolve(req.result || null); };
        req.onerror = function () { reject(req.error || new Error('indexeddb read failed')); };
      } catch (err) { reject(err); }
    });
  }

  async function deleteFile(id) {
    if (!id) return;
    memoryFiles.delete(id);
    const db = await openDb();
    if (!db) return;
    return new Promise(function (resolve) {
      try {
        const tx = db.transaction(DB_STORE, 'readwrite');
        tx.objectStore(DB_STORE).delete(id);
        tx.oncomplete = function () { resolve(true); };
        tx.onerror = function () { resolve(false); };
      } catch (_) { resolve(false); }
    });
  }

  async function clearFiles() {
    memoryFiles.clear();
    const db = await openDb();
    if (!db) return;
    return new Promise(function (resolve) {
      try {
        const tx = db.transaction(DB_STORE, 'readwrite');
        tx.objectStore(DB_STORE).clear();
        tx.oncomplete = function () { resolve(true); };
        tx.onerror = function () { resolve(false); };
      } catch (_) { resolve(false); }
    });
  }

  /* ── Mod library ─────────────────────────────────────────── */

  let mods = [];
  try {
    const raw = safeParse(localStorage.getItem(MODS_KEY), []);
    mods = Array.isArray(raw) ? raw.filter(function (m) { return m && typeof m === 'object' && m.id; }) : [];
  } catch (_) { mods = []; }

  function saveMods() {
    try { localStorage.setItem(MODS_KEY, JSON.stringify(mods)); } catch (_) {}
    document.dispatchEvent(new CustomEvent('soullink:mods', { detail: { mods: mods.slice() } }));
  }

  function addMod(record) {
    const now = Date.now();
    const existing = mods.find(function (m) { return m.id === record.id; });
    if (existing) {
      Object.assign(existing, record, { installDate: existing.installDate || now });
      if (record.blobId && existing.blobId && existing.blobId !== record.blobId) {
        deleteFile(existing.blobId).catch(function () {});
      }
    } else {
      const item = Object.assign({
        active: true,
        installDate: now,
        activatedAt: now,
        paletteIndex: derivePaletteIndex(record.id + ':' + (record.hash || record.name || '')),
        size: 0,
        kind: 'archive',
        source: 'local'
      }, record);
      mods.unshift(item);
    }
    saveMods();
    applyTheme();
    return mods;
  }

  function updateMod(id, patch) {
    const item = mods.find(function (m) { return m.id === id; });
    if (!item) return null;
    Object.assign(item, patch);
    saveMods();
    applyTheme();
    return item;
  }

  function setActive(id, active) {
    const item = mods.find(function (m) { return m.id === id; });
    if (!item) return;
    item.active = !!active;
    if (active) item.activatedAt = Date.now();
    saveMods();
    applyTheme();
  }

  async function removeMod(id) {
    const index = mods.findIndex(function (m) { return m.id === id; });
    if (index < 0) return;
    const item = mods[index];
    mods.splice(index, 1);
    if (item && item.blobId) {
      try { await deleteFile(item.blobId); } catch (_) {}
    }
    saveMods();
    applyTheme();
  }

  function findMod(id) {
    return mods.find(function (m) { return m.id === id; }) || null;
  }

  function activeMods() {
    return mods.filter(function (m) { return m.active; });
  }

  function themeMod() {
    const active = activeMods();
    if (!active.length) return null;
    return active.slice().sort(function (a, b) {
      return (b.activatedAt || 0) - (a.activatedAt || 0);
    })[0];
  }

  function derivePaletteIndex(seed) {
    let h = 2166136261;
    const text = String(seed || 'vanilla');
    for (let i = 0; i < text.length; i++) {
      h ^= text.charCodeAt(i);
      h = Math.imul(h, 16777619);
    }
    return Math.abs(h) % Math.max(1, palettes.length);
  }

  function paletteFor(mod) {
    if (!palettes.length) return null;
    if (mod && Number.isInteger(mod.paletteIndex) && palettes[mod.paletteIndex]) return palettes[mod.paletteIndex];
    if (mod && mod.palette) {
      const found = palettes.find(function (p) { return p.id === mod.palette; });
      if (found) return found;
    }
    return palettes[0];
  }

  function currentPalette() {
    return paletteFor(themeMod()) || palettes[0] || null;
  }

  function themeName() {
    const mod = themeMod();
    return mod ? mod.name : 'VANILLA';
  }

  function applyTheme() {
    const mod = themeMod();
    const palette = paletteFor(mod) || palettes[0];
    if (!palette) return;
    const root = document.documentElement;
    root.style.setProperty('--mod-accent', palette.accent);
    root.style.setProperty('--mod-accent-2', palette.accent2);
    root.style.setProperty('--mod-glow', palette.glow);
    if (mod) {
      document.body.classList.add('has-mod');
      document.body.setAttribute('data-mod', mod.id);
    } else {
      document.body.classList.remove('has-mod');
      document.body.removeAttribute('data-mod');
    }
    document.dispatchEvent(new CustomEvent('soullink:theme', { detail: { mod: mod, palette: palette } }));
  }

  function totalBytes() {
    return mods.reduce(function (sum, m) { return sum + (Number(m.size) || 0); }, 0);
  }

  async function resetAll() {
    try {
      localStorage.removeItem(SETTINGS_KEY);
      localStorage.removeItem(MODS_KEY);
    } catch (_) {}
    await clearFiles();
    mods = [];
    settings = Object.assign({}, defaults);
    applySettingsClasses();
    applyTheme();
    document.dispatchEvent(new CustomEvent('soullink:mods', { detail: { mods: [] } }));
    document.dispatchEvent(new CustomEvent('soullink:settings', { detail: { settings: settings } }));
  }

  /* ── Helpers ─────────────────────────────────────────────── */

  async function blobHash(blob) {
    try {
      if (window.crypto && crypto.subtle && blob) {
        const chunk = blob.slice(0, Math.min(blob.size, 1024 * 1024));
        const buf = await chunk.arrayBuffer();
        const digest = await crypto.subtle.digest('SHA-256', buf);
        return Array.from(new Uint8Array(digest)).slice(0, 12).map(function (b) {
          return b.toString(16).padStart(2, '0');
        }).join('');
      }
    } catch (_) {}
    return 'h' + Math.random().toString(16).slice(2) + '-' + (blob ? blob.size : 0);
  }

  async function inspectDataWin(blob) {
    if (!blob) return { valid: false, form: '', chunk: '' };
    try {
      const head = new Uint8Array(await blob.slice(0, 12).arrayBuffer());
      const text = String.fromCharCode.apply(null, Array.from(head));
      return {
        valid: text.slice(0, 4) === 'FORM' && text.slice(8, 12) === 'GEN8',
        form: text.slice(0, 4),
        chunk: text.slice(8, 12)
      };
    } catch (_) {
      return { valid: false, form: '', chunk: '' };
    }
  }

  function formatBytes(bytes) {
    const n = Number(bytes) || 0;
    if (n < 1024) return n + ' B';
    if (n < 1024 * 1024) return (n / 1024).toFixed(n < 10240 ? 1 : 0) + ' KB';
    if (n < 1024 * 1024 * 1024) return (n / (1024 * 1024)).toFixed(n < 10 * 1024 * 1024 ? 1 : 0) + ' MB';
    return (n / (1024 * 1024 * 1024)).toFixed(1) + ' GB';
  }

  function formatNumber(n) {
    const num = Number(n) || 0;
    if (num >= 1000000) return (num / 1000000).toFixed(1).replace('.0', '') + 'M';
    if (num >= 1000) return (num / 1000).toFixed(1).replace('.0', '') + 'K';
    return String(num);
  }

  function formatDate(ts) {
    if (!ts) return '';
    try {
      return new Intl.DateTimeFormat(SL.i18n.lang === 'ru' ? 'ru-RU' : 'en-US', {
        day: '2-digit', month: 'short', year: 'numeric'
      }).format(new Date(ts));
    } catch (_) {
      return new Date(ts).toLocaleDateString();
    }
  }

  window.SL = window.SL || {};
  SL.store = {
    get settings() { return settings; },
    get mods() { return mods.slice(); },
    loadSettings: loadSettings,
    saveSettings: saveSettings,
    applySettingsClasses: applySettingsClasses,
    addMod: addMod,
    updateMod: updateMod,
    setActive: setActive,
    removeMod: removeMod,
    findMod: findMod,
    activeMods: activeMods,
    themeMod: themeMod,
    currentPalette: currentPalette,
    themeName: themeName,
    paletteFor: paletteFor,
    applyTheme: applyTheme,
    derivePaletteIndex: derivePaletteIndex,
    putFile: putFile,
    getFile: getFile,
    deleteFile: deleteFile,
    clearFiles: clearFiles,
    resetAll: resetAll,
    totalBytes: totalBytes,
    blobHash: blobHash,
    inspectDataWin: inspectDataWin,
    formatBytes: formatBytes,
    formatNumber: formatNumber,
    formatDate: formatDate,
    settingsKey: SETTINGS_KEY,
    modsKey: MODS_KEY
  };
})();

/* SOUL LINK — THE SEAM. An original little pixel prologue drawn on a 480×320 canvas. */
(function () {
  'use strict';

  const W = 480;
  const H = 320;
  const ROOM = { x: 28, y: 52, w: 424, h: 238 };
  const GATE = { x: 210, y: 46, w: 60, h: 38 };
  const SAVE_POS = { x: 420, y: 86 };
  const PIP_POS = { x: 112, y: 152 };

  const DIRS = {
    up: { x: 0, y: -1, face: 'up' },
    down: { x: 0, y: 1, face: 'down' },
    left: { x: -1, y: 0, face: 'left' },
    right: { x: 1, y: 0, face: 'right' }
  };

  const DECOR = {
    crystals: [
      { x: 48, y: 84, s: 4, c: 1 }, { x: 72, y: 68, s: 3, c: 2 },
      { x: 406, y: 68, s: 5, c: 1 }, { x: 430, y: 102, s: 3, c: 2 },
      { x: 394, y: 276, s: 3, c: 1 }, { x: 64, y: 276, s: 4, c: 2 }
    ],
    grass: [
      { x: 86, y: 262 }, { x: 196, y: 92 }, { x: 302, y: 278 },
      { x: 374, y: 198 }, { x: 158, y: 222 }, { x: 252, y: 246 },
      { x: 408, y: 144 }, { x: 130, y: 96 }
    ],
    roots: [42, 96, 144, 356, 408, 438]
  };

  function clamp(v, min, max) { return v < min ? min : v > max ? max : v; }
  function dist2(ax, ay, bx, by) { const dx = ax - bx, dy = ay - by; return dx * dx + dy * dy; }
  function rnd(min, max) { return min + Math.random() * (max - min); }
  function t(key, vars) { return SL.i18n.t(key, vars); }

  class SeamGame {
    constructor() {
      this.canvas = null;
      this.ctx = null;
      this.raf = null;
      this.running = false;
      this.paused = false;
      this.loaded = false;
      this.keys = { up: false, down: false, left: false, right: false };
      this.last = 0;
      this.dialogTimer = null;
      this.toastTimer = null;
      this.loadRaf = null;
      this.time = 0;
      this.state = this.freshState();
      this.lastHud = {};
      this.assetsReady = true;
      this.boundLoop = this.loop.bind(this);
    }

    freshState() {
      return {
        mode: 'idle',
        player: {
          x: 240, y: 252, dir: 'down', hp: 20, maxHp: 20,
          speed: 78, invuln: 0, walk: 0, moving: false, blink: 0
        },
        petals: [
          { x: 370, y: 106, taken: false, phase: 0.4 },
          { x: 330, y: 246, taken: false, phase: 2.1 },
          { x: 80, y: 238, taken: false, phase: 4.2 }
        ],
        hazards: [
          { x: 188, y: 112, axis: 'x', min: 160, max: 300, phase: 0.4, speed: 0.55, dir: 1 },
          { x: 282, y: 190, axis: 'y', min: 126, max: 252, phase: 1.8, speed: 0.42, dir: -1 },
          { x: 140, y: 208, axis: 'x', min: 104, max: 170, phase: 3.4, speed: 0.7, dir: 1 }
        ],
        collected: 0,
        gateOpen: false,
        battleDone: false,
        dialogue: null,
        battle: null,
        stats: { hits: 0, elapsed: 0 },
        shake: 0,
        dust: [],
        saveCooldown: 0,
        ambient: 0,
        prompt: '',
        promptKind: ''
      };
    }

    mount(canvas) {
      this.canvas = canvas;
      this.ctx = canvas.getContext('2d', { alpha: false });
      this.ctx.imageSmoothingEnabled = false;
      this.seedDust();
    }

    seedDust() {
      const dust = [];
      for (let i = 0; i < 44; i++) {
        dust.push({
          x: rnd(0, W), y: rnd(0, H), s: Math.random() < 0.7 ? 1 : 2,
          vy: rnd(-4, -12), vx: rnd(-2, 2), a: rnd(0.12, 0.42),
          gold: Math.random() < 0.28, phase: rnd(0, Math.PI * 2)
        });
      }
      this.state.dust = dust;
    }

    start(opts) {
      if (!this.ctx) return;
      const options = opts || {};
      this.stopTimers();
      this.state = this.freshState();
      this.seedDust();
      this.paused = false;
      this.running = true;
      this.loaded = false;
      this.keys = { up: false, down: false, left: false, right: false };
      this.hideOverlays();
      this.hideDialog();
      this.setPrompt('');
      this.showLoading(true);
      this.runLoader(function () {
        this.loaded = true;
        this.showLoading(false);
        this.state.mode = 'explore';
        this.refreshHud(true);
        if (options.skipIntro) {
          this.afterIntro();
        } else {
          const self = this;
          window.setTimeout(function () {
            if (!self.running) return;
            self.startDialogue(SL.data.DIALOGUES[SL.i18n.lang].intro, function () { self.afterIntro(); });
          }, 260);
        }
      }.bind(this));
      if (!this.raf) {
        this.last = performance.now();
        this.raf = requestAnimationFrame(this.boundLoop);
      }
    }

    afterIntro() {
      this.state.mode = 'explore';
      this.setStatus(t('game.statusExplore'));
      this.setObjective(t('game.objectivePetal'));
      this.showToast(t('game.pickupToast', { n: 0 }), 900);
      this.refreshHud(true);
    }

    runLoader(done) {
      const reduce = SL.store.settings.reduceMotion;
      const duration = reduce ? 220 : 1280;
      const start = performance.now();
      const fill = document.getElementById('loading-fill');
      const log = document.getElementById('loading-log');
      const stages = ['DETERMINATION', 'ROOTS', 'ECHO', 'SOUL'];
      const self = this;
      if (this.loadRaf) cancelAnimationFrame(this.loadRaf);
      function tick(now) {
        const p = clamp((now - start) / duration, 0, 1);
        if (fill) fill.style.width = Math.round(p * 100) + '%';
        if (log) log.textContent = stages[Math.min(stages.length - 1, Math.floor(p * stages.length))];
        if (p < 1 && self.running) {
          self.loadRaf = requestAnimationFrame(tick);
        } else if (self.running) {
          self.loadRaf = null;
          done();
        }
      }
      if (fill) fill.style.width = '0%';
      this.loadRaf = requestAnimationFrame(tick);
    }

    showLoading(show) {
      const el = document.getElementById('game-loading');
      if (!el) return;
      if (show) el.classList.remove('is-done');
      else el.classList.add('is-done');
    }

    stopTimers() {
      if (this.dialogTimer) { clearTimeout(this.dialogTimer); this.dialogTimer = null; }
      if (this.toastTimer) { clearTimeout(this.toastTimer); this.toastTimer = null; }
      if (this.loadRaf) { cancelAnimationFrame(this.loadRaf); this.loadRaf = null; }
    }

    stop() {
      this.running = false;
      this.paused = false;
      this.stopTimers();
      if (this.raf) { cancelAnimationFrame(this.raf); this.raf = null; }
      this.hideDialog();
      this.setPrompt('');
      this.hideOverlays();
      this.showLoading(false);
    }

    pause() {
      if (!this.running || this.state.mode === 'dead' || this.state.mode === 'complete') return;
      this.paused = true;
      this.setPrompt('');
      this.refreshPause();
      const el = document.getElementById('pause-overlay');
      if (el) el.hidden = false;
    }

    resume() {
      this.paused = false;
      const el = document.getElementById('pause-overlay');
      if (el) el.hidden = true;
      this.last = performance.now();
    }

    isPaused() { return this.paused; }
    isRunning() { return this.running; }
    mode() { return this.state.mode; }

    setDirection(dir, pressed) {
      if (!DIRS[dir]) return;
      this.keys[dir] = !!pressed;
      if (pressed && this.state.mode === 'explore') {
        this.state.player.dir = dir;
      }
    }

    clearKeys() {
      this.keys = { up: false, down: false, left: false, right: false };
    }

    action() {
      if (!this.running || this.paused) return;
      const s = this.state;
      if (s.mode === 'dialogue') { this.advanceDialogue(); return; }
      if (s.mode === 'explore') {
        const near = this.nearbyInteractable();
        if (!near) return;
        if (near.kind === 'pip') this.talkToPip();
        else if (near.kind === 'save') this.touchSave();
        else if (near.kind === 'gate') this.touchGate();
        return;
      }
      if (s.mode === 'battle') {
        this.showGameToast(t('game.battleTitle'), 500);
      }
    }

    cancel() {
      if (!this.running) return;
      if (this.state.mode === 'dialogue') {
        if (this.dialogTyping) this.completeDialogueLine();
        else this.advanceDialogue();
        return;
      }
      if (this.paused) { this.resume(); return; }
      if (this.state.mode === 'explore' || this.state.mode === 'battle') {
        this.pause();
        if (SL.audio) SL.audio.sfx('back');
      }
    }

    nearbyInteractable() {
      const p = this.state.player;
      if (!this.state.battleDone && dist2(p.x, p.y, PIP_POS.x, PIP_POS.y) < 42 * 42) return { kind: 'pip' };
      if (this.state.gateOpen && Math.abs(p.x - 240) < 46 && p.y < 100) return { kind: 'gate' };
      if (dist2(p.x, p.y, SAVE_POS.x, SAVE_POS.y) < 34 * 34) return { kind: 'save' };
      if (Math.abs(p.x - 240) < 44 && p.y < 108) return { kind: 'gate' };
      return null;
    }

    talkToPip() {
      const s = this.state;
      const lang = SL.i18n.lang;
      if (s.collected < 3) {
        this.startDialogue(SL.data.DIALOGUES[lang].pipHint);
        if (SL.audio) SL.audio.sfx('confirm');
      } else if (!s.battleDone) {
        const self = this;
        this.startDialogue(SL.data.DIALOGUES[lang].pipDone, function () {
          self.startBattle();
        });
        if (SL.audio) SL.audio.sfx('confirm');
      } else {
        this.startDialogue([{ name: 'PIP', text: SL.i18n.lang === 'ru' ? 'Врата открыты. Я буду здесь, если решишь вернуться.' : 'The gate is open. I will be here if you decide to come back.' }]);
      }
    }

    touchSave() {
      const s = this.state;
      if (s.saveCooldown > 0) {
        this.startDialogue(SL.data.DIALOGUES[SL.i18n.lang].fullHp);
        return;
      }
      if (s.player.hp >= s.player.maxHp) {
        this.startDialogue(SL.data.DIALOGUES[SL.i18n.lang].fullHp);
        s.saveCooldown = 1.5;
        return;
      }
      s.player.hp = Math.min(s.player.maxHp, s.player.hp + 6);
      s.saveCooldown = 2.4;
      if (SL.audio) SL.audio.sfx('heal');
      this.startDialogue(SL.data.DIALOGUES[SL.i18n.lang].saved);
      this.showToast(t('game.saved'), 1200);
      this.refreshHud(true);
    }

    touchGate() {
      if (this.state.gateOpen) {
        this.complete();
      } else {
        this.startDialogue(SL.data.DIALOGUES[SL.i18n.lang].gateLocked);
      }
    }

    startDialogue(lines, onEnd) {
      if (!lines || !lines.length) { if (onEnd) onEnd(); return; }
      const s = this.state;
      s.mode = 'dialogue';
      s.dialogue = { lines: lines.slice(), index: 0, onEnd: onEnd || null };
      this.setPrompt('');
      this.showDialogLine();
    }

    showDialogLine() {
      const s = this.state;
      if (!s.dialogue) return;
      const line = s.dialogue.lines[s.dialogue.index];
      const box = document.getElementById('dialog-box');
      const nameEl = document.getElementById('dialog-name');
      const textEl = document.getElementById('dialog-text');
      if (!box || !textEl) return;
      if (nameEl) nameEl.textContent = line.name || '...';
      box.hidden = false;
      this.dialogFull = line.text;
      this.dialogShown = 0;
      this.dialogTyping = true;
      textEl.textContent = '';
      const self = this;
      const chars = Array.from(line.text);
      if (this.dialogTimer) clearTimeout(this.dialogTimer);
      const step = function () {
        if (!self.running || !self.state.dialogue) return;
        self.dialogShown += 1;
        textEl.textContent = chars.slice(0, self.dialogShown).join('');
        if (self.dialogShown >= chars.length) {
          self.dialogTyping = false;
          self.dialogTimer = null;
          if (SL.audio) SL.audio.sfx('move');
          return;
        }
        self.dialogTimer = setTimeout(step, 17);
      };
      step();
    }

    completeDialogueLine() {
      if (this.dialogTimer) { clearTimeout(this.dialogTimer); this.dialogTimer = null; }
      const textEl = document.getElementById('dialog-text');
      if (textEl) textEl.textContent = this.dialogFull || '';
      this.dialogTyping = false;
    }

    advanceDialogue() {
      const s = this.state;
      if (!s.dialogue) return;
      if (this.dialogTyping) { this.completeDialogueLine(); return; }
      if (SL.audio) SL.audio.sfx('move');
      s.dialogue.index += 1;
      if (s.dialogue.index >= s.dialogue.lines.length) {
        const onEnd = s.dialogue.onEnd;
        s.dialogue = null;
        this.hideDialog();
        if (onEnd) onEnd();
        else s.mode = 'explore';
        return;
      }
      this.showDialogLine();
    }

    hideDialog() {
      if (this.dialogTimer) { clearTimeout(this.dialogTimer); this.dialogTimer = null; }
      this.dialogTyping = false;
      const box = document.getElementById('dialog-box');
      if (box) box.hidden = true;
    }

    startBattle() {
      const s = this.state;
      s.mode = 'battle';
      s.battle = {
        duration: 15,
        left: 15,
        elapsed: 0,
        spawn: 0,
        bullets: [],
        box: { x: 138, y: 152, w: 204, h: 116 },
        soul: { x: 240, y: 210, r: 3 }
      };
      s.player.invuln = 0.8;
      this.setStatus(t('game.statusBattle'));
      this.setObjective(t('game.objectiveBattle'));
      this.setPrompt('');
      const banner = document.getElementById('battle-banner');
      if (banner) banner.hidden = false;
      this.refreshBattleHud();
      this.showToast(t('game.battleStart'), 1800);
      if (SL.audio) SL.audio.sfx('battle');
    }

    endBattle() {
      const s = this.state;
      s.battle = null;
      s.battleDone = true;
      s.gateOpen = true;
      s.mode = 'explore';
      s.player.hp = Math.min(s.player.maxHp, s.player.hp + 4);
      const banner = document.getElementById('battle-banner');
      if (banner) banner.hidden = true;
      this.setStatus(t('game.statusGate'));
      this.setObjective(t('game.objectiveGate'));
      if (SL.audio) SL.audio.sfx('gate');
      const self = this;
      this.startDialogue(SL.data.DIALOGUES[SL.i18n.lang].battleSurvived, function () {
        self.state.mode = 'explore';
      });
      this.refreshHud(true);
    }

    complete() {
      const s = this.state;
      if (s.mode === 'complete') return;
      s.mode = 'complete';
      this.setPrompt('');
      this.setStatus(t('game.statusComplete'));
      this.setObjective('');
      if (SL.audio) SL.audio.sfx('gate');
      this.refreshHud(true);
      const overlay = document.getElementById('complete-overlay');
      if (overlay) overlay.hidden = false;
      const timeEl = document.getElementById('complete-time');
      const hitsEl = document.getElementById('complete-hits');
      const modEl = document.getElementById('complete-mod');
      if (timeEl) timeEl.textContent = this.formatTime(s.stats.elapsed);
      if (hitsEl) hitsEl.textContent = String(s.stats.hits);
      if (modEl) modEl.textContent = SL.store.themeName();
      this.showToast(t('game.completedToast'), 2200);
    }

    die() {
      const s = this.state;
      s.mode = 'dead';
      this.setPrompt('');
      this.clearKeys();
      this.setStatus(t('game.deathToast'));
      if (SL.audio) SL.audio.sfx('hurt');
      const overlay = document.getElementById('death-overlay');
      if (overlay) overlay.hidden = false;
    }

    retry() {
      const overlay = document.getElementById('death-overlay');
      if (overlay) overlay.hidden = true;
      this.start({ skipIntro: true });
    }

    hideOverlays() {
      ['pause-overlay', 'complete-overlay', 'death-overlay'].forEach(function (id) {
        const el = document.getElementById(id);
        if (el) el.hidden = true;
      });
      const banner = document.getElementById('battle-banner');
      if (banner) banner.hidden = true;
    }

    refreshPause() {
      const s = this.state;
      const petals = document.getElementById('pause-petals');
      const hp = document.getElementById('pause-hp');
      const time = document.getElementById('pause-time');
      if (petals) petals.textContent = String(s.collected);
      if (hp) hp.textContent = String(s.player.hp);
      if (time) time.textContent = this.formatTime(s.stats.elapsed);
    }

    loop(now) {
      this.raf = requestAnimationFrame(this.boundLoop);
      const dt = Math.min(0.04, Math.max(0, (now - this.last) / 1000 || 0));
      this.last = now;
      if (!this.running) return;
      if (!this.paused) this.update(dt);
      this.draw(now / 1000);
    }

    update(dt) {
      const s = this.state;
      this.time += dt;
      const p = s.player;
      if (p.invuln > 0) p.invuln = Math.max(0, p.invuln - dt);
      if (s.saveCooldown > 0) s.saveCooldown = Math.max(0, s.saveCooldown - dt);
      if (s.shake > 0) s.shake = Math.max(0, s.shake - dt * 7);

      // dust always drifts
      s.dust.forEach(function (d) {
        d.y += d.vy * dt;
        d.x += d.vx * dt;
        if (d.y < -4) { d.y = H + 4; d.x = rnd(0, W); }
        if (d.x < -4) d.x = W + 4;
        if (d.x > W + 4) d.x = -4;
      });

      if (s.mode === 'explore' || s.mode === 'battle') s.stats.elapsed += dt;
      if (s.mode === 'dead' || s.mode === 'complete' || s.mode === 'dialogue') {
        this.updatePrompt();
        this.refreshHud();
        return;
      }

      if (s.mode === 'explore') {
        this.updateExplore(dt);
        this.updatePrompt();
      } else if (s.mode === 'battle') {
        this.updateBattle(dt);
      }
      this.refreshHud();
    }

    updateExplore(dt) {
      const s = this.state;
      const p = s.player;
      let dx = (this.keys.right ? 1 : 0) - (this.keys.left ? 1 : 0);
      let dy = (this.keys.down ? 1 : 0) - (this.keys.up ? 1 : 0);
      p.moving = !!(dx || dy);
      if (p.moving) {
        const len = Math.hypot(dx, dy) || 1;
        dx /= len; dy /= len;
        p.x += dx * p.speed * dt;
        p.y += dy * p.speed * dt;
        p.walk += dt;
        if (Math.abs(dx) > Math.abs(dy)) p.dir = dx > 0 ? 'right' : 'left';
        else p.dir = dy > 0 ? 'down' : 'up';
        if (Math.random() < dt * 4 && SL.audio) SL.audio.sfx('move');
      } else {
        p.walk += dt * 0.2;
      }
      const minX = ROOM.x + 12, maxX = ROOM.x + ROOM.w - 12;
      let minY = ROOM.y + 14;
      const maxY = ROOM.y + ROOM.h - 12;
      if (s.gateOpen && p.x > GATE.x + 10 && p.x < GATE.x + GATE.w - 10) minY = 70;
      p.x = clamp(p.x, minX, maxX);
      p.y = clamp(p.y, minY, maxY);
      if (s.gateOpen && p.y < 72 && p.x > GATE.x - 10 && p.x < GATE.x + GATE.w + 10) {
        this.complete();
        return;
      }

      // hazards move
      s.hazards.forEach(function (h) {
        const t = s.stats.elapsed * h.speed + h.phase;
        if (h.axis === 'x') h.x = (h.min + h.max) / 2 + Math.sin(t) * (h.max - h.min) / 2;
        else h.y = (h.min + h.max) / 2 + Math.sin(t) * (h.max - h.min) / 2;
      });

      // petal pickups
      for (let i = 0; i < s.petals.length; i++) {
        const petal = s.petals[i];
        if (petal.taken) continue;
        if (dist2(p.x, p.y, petal.x, petal.y) < 19 * 19) {
          petal.taken = true;
          s.collected += 1;
          s.stats.score = s.collected;
          if (SL.audio) SL.audio.sfx('pickup');
          this.showToast(t('game.pickupToast', { n: s.collected }), 1100);
          if (s.collected >= 3) {
            this.setStatus(t('game.statusReturn'));
            this.setObjective(t('game.objectiveReturn'));
          } else {
            this.setStatus(t('game.statusPetal'));
            this.setObjective(t('game.objectivePetal'));
          }
          this.refreshHud(true);
        }
      }

      // hazard collision
      if (p.invuln <= 0) {
        for (let i = 0; i < s.hazards.length; i++) {
          const h = s.hazards[i];
          if (dist2(p.x, p.y, h.x, h.y) < 17 * 17) {
            p.hp = Math.max(0, p.hp - 2);
            p.invuln = 1.15;
            s.stats.hits += 1;
            s.shake = 1;
            if (SL.audio) SL.audio.sfx('hurt');
            this.showToast(t('game.hurtToast'), 450);
            this.refreshHud(true);
            if (p.hp <= 0) { this.die(); return; }
            break;
          }
        }
      }

      // if all petals and battle not done, maybe pip prompt
      if (s.collected >= 3 && !s.battleDone) {
        this.setObjective(t('game.objectiveReturn'));
      }
    }

    updateBattle(dt) {
      const s = this.state;
      const b = s.battle;
      if (!b) return;
      const p = s.player;
      b.elapsed += dt;
      b.left = Math.max(0, b.duration - b.elapsed);
      let dx = (this.keys.right ? 1 : 0) - (this.keys.left ? 1 : 0);
      let dy = (this.keys.down ? 1 : 0) - (this.keys.up ? 1 : 0);
      if (dx || dy) {
        const len = Math.hypot(dx, dy) || 1;
        b.soul.x = clamp(b.soul.x + (dx / len) * 92 * dt, b.box.x + 7, b.box.x + b.box.w - 7);
        b.soul.y = clamp(b.soul.y + (dy / len) * 92 * dt, b.box.y + 7, b.box.y + b.box.h - 7);
      }
      b.spawn -= dt;
      const stage = b.elapsed < 5 ? 0 : b.elapsed < 10 ? 1 : 2;
      const interval = stage === 0 ? 0.58 : stage === 1 ? 0.44 : 0.34;
      if (b.spawn <= 0) {
        b.spawn = interval;
        if (stage === 0) {
          b.bullets.push({
            x: rnd(b.box.x + 10, b.box.x + b.box.w - 10), y: b.box.y + 2,
            vx: rnd(-8, 8), vy: rnd(52, 76), r: 3, kind: 'shard', spin: rnd(0, 6)
          });
        } else if (stage === 1) {
          const fromLeft = Math.random() < 0.5;
          b.bullets.push({
            x: fromLeft ? b.box.x + 2 : b.box.x + b.box.w - 2,
            y: rnd(b.box.y + 10, b.box.y + b.box.h - 10),
            vx: (fromLeft ? 1 : -1) * rnd(58, 82), vy: rnd(-6, 6),
            r: 3, kind: 'shard', spin: rnd(0, 6)
          });
        } else {
          const fromLeft = Math.random() < 0.5;
          if (Math.random() < 0.55) {
            b.bullets.push({
              x: rnd(b.box.x + 10, b.box.x + b.box.w - 10), y: b.box.y + b.box.h - 2,
              vx: rnd(-10, 10), vy: -rnd(62, 90), r: 3, kind: 'shard', spin: rnd(0, 6)
            });
          } else {
            b.bullets.push({
              x: fromLeft ? b.box.x + 2 : b.box.x + b.box.w - 2,
              y: rnd(b.box.y + 10, b.box.y + b.box.h - 10),
              vx: (fromLeft ? 1 : -1) * rnd(70, 92), vy: rnd(-12, 12),
              r: 3, kind: 'shard', spin: rnd(0, 6)
            });
          }
        }
        if (b.elapsed > 10 && Math.random() < 0.35) {
          b.bullets.push({
            x: rnd(b.box.x + 20, b.box.x + b.box.w - 20), y: b.box.y + 3,
            vx: 0, vy: rnd(70, 95), r: 2, kind: 'orb', spin: 0
          });
        }
      }
      for (let i = b.bullets.length - 1; i >= 0; i--) {
        const bullet = b.bullets[i];
        bullet.x += bullet.vx * dt;
        bullet.y += bullet.vy * dt;
        if (bullet.x < b.box.x - 20 || bullet.x > b.box.x + b.box.w + 20 ||
            bullet.y < b.box.y - 20 || bullet.y > b.box.y + b.box.h + 20) {
          b.bullets.splice(i, 1);
          continue;
        }
        if (p.invuln <= 0 && dist2(b.soul.x, b.soul.y, bullet.x, bullet.y) < (bullet.r + 4) * (bullet.r + 4)) {
          p.hp = Math.max(0, p.hp - 2);
          p.invuln = 1.05;
          s.stats.hits += 1;
          s.shake = 1;
          b.bullets.splice(i, 1);
          if (SL.audio) SL.audio.sfx('hurt');
          this.refreshHud(true);
          if (p.hp <= 0) { this.die(); return; }
        }
      }
      this.refreshBattleHud();
      if (b.elapsed >= b.duration) {
        const banner = document.getElementById('battle-banner');
        if (banner) banner.hidden = true;
        this.endBattle();
      }
    }

    updatePrompt() {
      const s = this.state;
      if (s.mode !== 'explore') { this.setPrompt(''); return; }
      const near = this.nearbyInteractable();
      if (near) {
        if (near.kind === 'pip') this.setPrompt(t('game.hintTalk'));
        else if (near.kind === 'save') this.setPrompt(t('game.hintSave'));
        else if (near.kind === 'gate') this.setPrompt(t('game.hintGate'));
      } else {
        this.setPrompt('');
      }
    }

    setPrompt(text) {
      if (this.state.prompt === text) return;
      this.state.prompt = text;
      const el = document.getElementById('game-prompt');
      const label = document.getElementById('game-prompt-text');
      if (!el || !label) return;
      if (text) {
        label.textContent = text;
        el.hidden = false;
      } else {
        el.hidden = true;
      }
    }

    showToast(text, duration) {
      if (!text) return;
      const el = document.getElementById('game-toast');
      if (!el) return;
      el.textContent = text;
      el.hidden = false;
      if (this.toastTimer) clearTimeout(this.toastTimer);
      const self = this;
      this.toastTimer = setTimeout(function () {
        el.hidden = true;
        self.toastTimer = null;
      }, duration || 1000);
    }

    showGameToast(text, duration) { this.showToast(text, duration); }

    setStatus(text) {
      const el = document.getElementById('game-status');
      if (el) el.textContent = text;
    }

    setObjective(text) {
      const el = document.getElementById('game-objective');
      if (el) el.textContent = text;
    }

    refreshHud(force) {
      const s = this.state;
      const p = s.player;
      const petals = document.getElementById('hud-petals');
      const hp = document.getElementById('hud-hp');
      const fill = document.getElementById('hud-hp-fill');
      if (petals) petals.textContent = String(s.collected);
      if (hp) hp.textContent = String(p.hp);
      if (fill) fill.style.width = Math.max(0, (p.hp / p.maxHp) * 100) + '%';
      if (force) {
        const mod = document.getElementById('hud-mod');
        const chip = document.getElementById('game-mod-chip');
        const name = SL.store.themeName();
        if (mod) mod.textContent = name === 'VANILLA' ? 'VANILLA' : name;
        if (chip) chip.textContent = name === 'VANILLA' ? 'VANILLA' : name;
      }
      this.lastHud = { petals: s.collected, hp: p.hp, mode: s.mode };
    }

    refreshBattleHud() {
      const s = this.state;
      if (!s.battle) return;
      const fill = document.getElementById('battle-timer-fill');
      const timer = document.getElementById('battle-timer');
      const pct = Math.max(0, s.battle.left / s.battle.duration);
      if (fill) fill.style.width = (pct * 100) + '%';
      if (timer) timer.textContent = s.battle.left.toFixed(1);
    }

    formatTime(seconds) {
      const total = Math.max(0, Math.floor(seconds || 0));
      const m = Math.floor(total / 60);
      const sec = total % 60;
      return String(m).padStart(2, '0') + ':' + String(sec).padStart(2, '0');
    }

    draw(now) {
      const ctx = this.ctx;
      if (!ctx) return;
      const p = SL.store.currentPalette() || { accent: '#ff3355' };
      const s = this.state;
      ctx.save();
      if (SL.store.settings.shake && s.shake > 0) {
        const mag = s.shake * 3;
        ctx.translate((Math.random() - 0.5) * mag, (Math.random() - 0.5) * mag);
      }
      this.drawRoom(ctx, p, now);
      this.drawGate(ctx, p, now);
      this.drawDecor(ctx, p, now);
      this.drawHazards(ctx, p, now);
      this.drawPetals(ctx, p, now);
      this.drawSave(ctx, p, now);
      this.drawPip(ctx, p, now);
      if (s.mode !== 'battle') this.drawPlayer(ctx, p, now);
      this.drawDust(ctx, p, now);
      if (s.mode === 'battle') this.drawBattle(ctx, p, now);
      if (s.mode === 'dead') {
        ctx.fillStyle = 'rgba(25,0,8,0.4)';
        ctx.fillRect(0, 0, W, H);
      }
      ctx.restore();
    }

    drawRoom(ctx, p, now) {
      const g = ctx.createLinearGradient(0, 0, 0, H);
      g.addColorStop(0, p.bg0);
      g.addColorStop(0.5, p.bg1);
      g.addColorStop(1, p.bg2);
      ctx.fillStyle = g;
      ctx.fillRect(0, 0, W, H);

      // walls
      ctx.fillStyle = p.wall;
      ctx.fillRect(0, 0, W, ROOM.y);
      ctx.fillRect(0, 0, ROOM.x, H);
      ctx.fillRect(ROOM.x + ROOM.w, 0, W - (ROOM.x + ROOM.w), H);
      ctx.fillRect(0, ROOM.y + ROOM.h, W, H - (ROOM.y + ROOM.h));

      // wall bricks
      ctx.fillStyle = p.wallAlt;
      for (let y = 4; y < ROOM.y; y += 12) {
        for (let x = 0; x < W; x += 28) {
          const off = (Math.floor(y / 12) % 2) * 14;
          ctx.fillRect(x + off, y, 25, 1);
          ctx.fillRect(x + off, y + 1, 1, 10);
        }
      }
      for (let x = 0; x < ROOM.x; x += 14) {
        for (let y = ROOM.y; y < H; y += 18) ctx.fillRect(x, y, 11, 1);
      }
      for (let x = ROOM.x + ROOM.w; x < W; x += 14) {
        for (let y = ROOM.y; y < H; y += 18) ctx.fillRect(x, y, 11, 1);
      }
      for (let y = ROOM.y + ROOM.h; y < H; y += 12) {
        for (let x = 0; x < W; x += 24) ctx.fillRect(x + (y % 24 ? 10 : 0), y, 19, 1);
      }

      // inner edge
      ctx.fillStyle = p.wallEdge;
      ctx.fillRect(ROOM.x - 2, ROOM.y, 2, ROOM.h);
      ctx.fillRect(ROOM.x + ROOM.w, ROOM.y, 2, ROOM.h);
      ctx.fillRect(ROOM.x - 2, ROOM.y - 2, ROOM.w + 4, 2);
      ctx.fillRect(ROOM.x - 2, ROOM.y + ROOM.h, ROOM.w + 4, 2);

      // floor checker
      for (let y = ROOM.y; y < ROOM.y + ROOM.h; y += 28) {
        for (let x = ROOM.x; x < ROOM.x + ROOM.w; x += 28) {
          const odd = ((x / 28) + (y / 28)) % 2 === 0;
          ctx.fillStyle = odd ? p.floor : p.floorAlt;
          ctx.fillRect(x, y, 28, 28);
        }
      }
      // floor noise
      ctx.fillStyle = p.wall;
      for (let i = 0; i < 60; i++) {
        const x = ROOM.x + ((i * 83) % ROOM.w);
        const y = ROOM.y + ((i * 47) % ROOM.h);
        ctx.globalAlpha = 0.18;
        ctx.fillRect(x, y, 2, 1);
      }
      ctx.globalAlpha = 1;

      // roots from the top
      ctx.fillStyle = p.wallAlt;
      DECOR.roots.forEach(function (rx, idx) {
        let x = rx;
