      });
    }

    drawGate(ctx, p, now) {
      const x = GATE.x, y = 18, w = GATE.w, h = 66;
      ctx.fillStyle = p.wallAlt;
      ctx.fillRect(x - 8, y + 8, 8, h);
      ctx.fillRect(x + w, y + 8, 8, h);
      ctx.fillStyle = p.wallEdge;
      ctx.fillRect(x - 10, y + 6, 10, 3);
