        ctx.fillStyle = p.danger;
        ctx.fillRect(h.x - 3, h.y - 5 + bob, 6, 10);
        ctx.fillRect(h.x - 5, h.y - 3 + bob, 10, 6);
        ctx.fillStyle = '#fff';
        ctx.fillRect(h.x - 1, h.y - 2 + bob, 2, 4);
