        ctx.fillStyle = p.gold;
        ctx.fillRect(-2, -7, 4, 4);
        ctx.fillRect(-7, -4, 4, 4);
        ctx.fillRect(3, -4, 4, 4);
        ctx.fillRect(-5, 0, 4, 4);
