      ctx.fillRect(ex + 26, ey + 8, 10, 8);
      ctx.fillStyle = '#f8f2ff';
      ctx.fillRect(ex - 12, ey - 9, 24, 14);
      ctx.fillStyle = p.accent;
      ctx.fillRect(ex - 5, ey - 6, 10, 8);
      ctx.fillStyle = '#0b0710';
      ctx.fillRect(ex - 1, ey - 5, 2, 6);
