      ctx.fillStyle = p.accent;
      ctx.fillRect(b.soul.x - 6, b.soul.y - 6, 12, 12);
      ctx.globalAlpha = 1;
    }
  }

  const game = new SeamGame();

  window.SL = window.SL || {};
