    } catch (err) {
      state.live = false;
      setApiStatus('offline');
      if (!state.catalog.length) {
        state.catalog = SL.data.FALLBACK_MODS.map(function (m) { return Object.assign({}, m); });
        state.total = 534;
        state.hasMore = false;
        chooseFeatured();
        renderAll();
      }
      if (window.console) console.warn('[SOUL LINK] GameBanana feed:', err && err.message);
    } finally {
      state.loading = false;
      updateSyncLabel();
    }
  }

  function setApiStatus(kind) {
    const net = $id('net-pill');
    const netLabel = $id('net-label');
    const footerNet = $id('footer-net');
    const apiState = $id('api-state');
    const sync = $id('mods-sync');
    const labels = {
      loading: t('common.connecting'),
      online: t('common.online'),
      offline: t('common.cached')
    };
    if (net) {
      net.classList.toggle('is-online', kind === 'online');
      net.classList.toggle('is-offline', kind === 'offline');
    }
    if (netLabel) netLabel.textContent = labels[kind] || labels.loading;
    if (footerNet) {
      footerNet.classList.toggle('is-online', kind === 'online');
      footerNet.classList.toggle('is-offline', kind === 'offline');
      const span = footerNet.querySelector('span');
      if (span) span.textContent = labels[kind] || labels.loading;
    }
    if (apiState) {
      apiState.classList.toggle('is-online', kind === 'online');
      apiState.classList.toggle('is-offline', kind === 'offline');
      const span = apiState.querySelector('span');
      if (span) span.textContent = kind === 'online' ? t('mods.apiOnline') : kind === 'offline' ? t('mods.apiOffline') : t('common.connecting');
    }
    if (sync) sync.textContent = kind === 'online' ? t('mods.synced') : kind === 'offline' ? t('mods.apiFallback').toUpperCase() : t('mods.syncing');
  }
  function updateSyncLabel() {
    if (state.loading) return;
    const sync = $id('mods-sync');
    if (sync) sync.textContent = state.live ? t('mods.synced') : t('mods.apiFallback').toUpperCase();
  }

  function chooseFeatured() {
    state.featured = state.catalog.find(function (m) { return m.id === 669734; }) ||
      state.catalog.slice().sort(function (a, b) { return (b.views || 0) - (a.views || 0); })[0] || null;
    updateFeatured();
  }

  function updateFeatured() {
    const mod = state.featured;
    const card = $id('featured-card');
    if (!mod || !card) return;
    const img = $id('featured-image');
    const wrap = img ? img.closest('.featured-media') : null;
    if (img) {
      img.alt = mod.name;
      img.onload = function () { if (wrap) wrap.classList.add('has-image'); };
      img.onerror = function () { if (wrap) wrap.classList.remove('has-image'); img.removeAttribute('src'); };
      img.src = mod.thumb || '';
      if (img.complete && img.naturalWidth) wrap.classList.add('has-image');
    }
    const title = $id('featured-title');
    const author = $id('featured-author');
    const cat = $id('featured-category');
    const views = $id('featured-views');
    const likes = $id('featured-likes');
    const version = $id('featured-version');
    if (title) title.textContent = mod.name;
    if (author) author.textContent = mod.author;
    if (cat) cat.textContent = categoryLabel(mod.category);
    if (views) views.textContent = SL.store.formatNumber(mod.views);
    if (likes) likes.textContent = SL.store.formatNumber(mod.likes);
    if (version) version.textContent = mod.version || '—';
    card.classList.add('is-ready');
  }

  /* ── Render browse ──────────────────────────────────────── */

  function filteredCatalog() {
    let list = state.catalog.slice();
    if (state.category !== 'all') {
      list = list.filter(function (m) { return String(m.category).toLowerCase() === state.category; });
    }
    const q = state.query.trim().toLowerCase();
    if (q) {
      list = list.filter(function (m) {
        return (m.name + ' ' + m.author + ' ' + m.category + ' ' + m.version).toLowerCase().indexOf(q) >= 0;
      });
    }
    const sort = state.sort;
    if (sort === 'popular') list.sort(function (a, b) { return (b.views + b.likes * 40) - (a.views + a.likes * 40); });
    else if (sort === 'new') list.sort(function (a, b) { return (b.ts || 0) - (a.ts || 0); });
    else if (sort === 'name') list.sort(function (a, b) { return a.name.localeCompare(b.name); });
    else {
      const order = {};
      state.catalog.forEach(function (m, i) { order[m.id] = i; });
      list.sort(function (a, b) { return (order[a.id] || 0) - (order[b.id] || 0); });
    }
    return list;
  }

  function renderBrowse() {
    const grid = $id('mod-grid');
    if (!grid) return;
    const list = filteredCatalog();
    grid.textContent = '';
    const empty = $id('mods-empty');
    if (empty) empty.hidden = list.length > 0;
    const wrap = $id('load-more-wrap');
    if (wrap) wrap.hidden = !state.hasMore || state.live === false || list.length === 0;
    list.forEach(function (mod) { grid.appendChild(modCard(mod)); });
    if (!list.length && state.catalog.length && state.live !== false) {
      // Filter produced no matches; keep empty state.
    }
  }

  function modCard(mod) {
    const card = el('article', 'mod-card');
    card.dataset.modId = String(mod.id);
    const thumbBtn = el('button', 'mod-thumb');
    thumbBtn.type = 'button';
    thumbBtn.setAttribute('aria-label', mod.name);
    const img = document.createElement('img');
    img.loading = 'lazy';
    img.alt = '';
    img.referrerPolicy = 'no-referrer';
    if (mod.thumb) {
      img.src = mod.thumb;
      img.onerror = function () { thumbBtn.classList.add('is-broken'); img.removeAttribute('src'); };
    } else {
      thumbBtn.classList.add('is-broken');
    }
    const fallback = el('span', 'thumb-fallback');
    fallback.appendChild(icon('spark'));
    const badges = el('span', 'mod-badges');
    const srcBadge = el('span', 'mod-badge', mod.source === 'gamebanana' ? 'GB' : 'LOCAL');
    badges.appendChild(srcBadge);
    if (isInstalled(mod.id)) badges.appendChild(el('span', 'mod-badge installed', '✓'));
    const idLabel = el('span', 'mod-id', '#' + mod.id);
    append(thumbBtn, img, fallback, badges, idLabel);
    thumbBtn.addEventListener('click', function () { openDetail(mod.id); });

    const body = el('div', 'mod-body');
    const title = el('h3', 'mod-title', mod.name);
    const author = el('div', 'mod-author', t('mods.by', { author: mod.author }));
    const meta = el('div', 'mod-meta');
    const views = el('span');
    append(views, icon('eye'), document.createTextNode(SL.store.formatNumber(mod.views)));
    const likes = el('span');
    append(likes, icon('heart'), document.createTextNode(SL.store.formatNumber(mod.likes)));
    const cat = el('span', '', categoryLabel(mod.category));
    append(meta, views, likes, cat);
    const actions = el('div', 'mod-actions');
    const open = el('button', 'pixel-button small');
    open.type = 'button';
    append(open, icon('download'), el('span', '', isInstalled(mod.id) ? t('mods.installedState') : t('common.install')));
    open.addEventListener('click', function () { openDetail(mod.id); });
    const details = el('button', 'pixel-button small ghost icon-only');
    details.type = 'button';
    details.setAttribute('aria-label', t('common.details'));
    details.appendChild(icon('arrow-right'));
    details.addEventListener('click', function () { openDetail(mod.id); });
    append(actions, open, details);
    append(body, title, author, meta, actions);
    append(card, thumbBtn, body);
    return card;
  }

  /* ── Installed ──────────────────────────────────────────── */

  function kindLabel(kind) {
    if (kind === 'datawin') return t('mods.kindDatawin');
    if (kind === 'patch') return t('mods.kindPatch');
    if (kind === 'theme') return t('mods.kindTheme');
    return t('mods.kindArchive');
  }

  function renderInstalled() {
    const list = $id('installed-list');
    const empty = $id('installed-empty');
    if (!list) return;
    const mods = SL.store.mods.slice().sort(function (a, b) { return (b.installDate || 0) - (a.installDate || 0); });
    list.textContent = '';
    if (empty) empty.hidden = mods.length > 0;
    mods.forEach(function (mod) { list.appendChild(installedCard(mod)); });
    updateCounts();
  }

  function installedCard(mod) {
    const palette = SL.store.paletteFor(mod) || { accent: '#ff3355' };
    const card = el('article', 'installed-card' + (mod.active ? ' is-active' : ''));
    card.dataset.installedId = mod.id;
    card.style.setProperty('--card-accent', palette.accent);
    const thumb = el('div', 'installed-thumb');
    if (mod.thumbnail) {
      const img = document.createElement('img');
      img.src = mod.thumbnail;
      img.alt = '';
      img.referrerPolicy = 'no-referrer';
      img.onerror = function () { img.remove(); thumb.appendChild(icon('cube')); };
      thumb.appendChild(img);
    } else {
      thumb.appendChild(icon(mod.kind === 'theme' ? 'spark' : mod.kind === 'patch' ? 'file' : 'cube'));
    }

    const main = el('div', 'installed-main');
    const name = el('div', 'installed-name');
    name.appendChild(document.createTextNode(mod.name));
    if (mod.active) name.appendChild(el('span', 'status-chip', t('mods.activeState')));
    const sub = el('div', 'installed-sub');
    const source = el('span', '', mod.source === 'gamebanana' ? t('mods.sourceGb') : mod.source === 'demo' ? t('mods.demoAuthor') : t('mods.sourceLocal'));
    const kind = el('span', 'installed-kind', kindLabel(mod.kind));
    const size = el('span', '', mod.size ? SL.store.formatBytes(mod.size) : '—');
    const date = el('span', '', t('mods.installedOn', { date: SL.store.formatDate(mod.installDate) }));
    append(sub, source, kind, size, date);
    if (mod.validDataWin) {
      const valid = el('span', '', 'FORM/GEN8');
      valid.style.color = 'var(--green)';
      sub.appendChild(valid);
    }
    append(main, name, sub);

    const actions = el('div', 'installed-actions');
    const toggle = el('button', 'install-toggle' + (mod.active ? ' is-active' : ''));
    toggle.type = 'button';
    toggle.setAttribute('aria-pressed', mod.active ? 'true' : 'false');
    append(toggle, el('i'), el('span', '', mod.active ? t('common.active') : t('common.inactive')));
    toggle.addEventListener('click', function () {
      SL.store.setActive(mod.id, !mod.active);
      if (SL.audio) SL.audio.sfx(mod.active ? 'back' : 'confirm');
      SL.ui.toast(mod.active ? t('mods.deactivated') : t('mods.activated', { name: mod.name }), '', 'success', 'check');
      renderAll();
    });
    actions.appendChild(toggle);

    if (mod.blobId) {
      const exportBtn = el('button', 'icon-action');
      exportBtn.type = 'button';
      exportBtn.title = t('mods.export');
      exportBtn.setAttribute('aria-label', t('mods.export'));
      exportBtn.appendChild(icon('download'));
      exportBtn.addEventListener('click', function () { exportMod(mod); });
      actions.appendChild(exportBtn);
    }
    if (mod.sourceUrl) {
      const link = document.createElement('a');
      link.className = 'icon-action';
      link.href = mod.sourceUrl;
      link.target = '_blank';
      link.rel = 'noopener noreferrer';
      link.title = 'GameBanana';
      link.setAttribute('aria-label', 'GameBanana');
      link.appendChild(icon('external'));
      actions.appendChild(link);
    }
    const del = el('button', 'icon-action danger');
    del.type = 'button';
    del.title = t('common.delete');
    del.setAttribute('aria-label', t('common.delete'));
    del.appendChild(icon('trash'));
    del.addEventListener('click', function () { askDelete(mod); });
    actions.appendChild(del);

    append(card, thumb, main, actions);
    return card;
  }

  function askDelete(mod) {
    SL.ui.confirm({
      title: t('mods.deleteTitle'),
      copy: t('mods.deleteCopy', { name: mod.name }),
      confirmText: t('mods.deleteButton'),
      cancelText: t('common.cancel'),
      danger: true,
      icon: 'trash'
    }).then(function (ok) {
      if (!ok) return;
      SL.store.removeMod(mod.id).then(function () {
        SL.audio.sfx('delete');
        SL.ui.toast(t('mods.deleted'), '', 'success', 'trash');
        renderAll();
      });
    });
  }

  async function exportMod(mod) {
    try {
      const blob = mod.blobId ? await SL.store.getFile(mod.blobId) : null;
      if (!blob) { SL.ui.toast(t('mods.exportUnavailable'), '', 'warning', 'warning'); return; }
      const a = document.createElement('a');
      const url = URL.createObjectURL(blob);
      a.href = url;
      a.download = mod.fileName || (mod.name.replace(/[^\w.-]+/g, '_') + '.win');
      document.body.appendChild(a);
      a.click();
      a.remove();
      setTimeout(function () { URL.revokeObjectURL(url); }, 1500);
      SL.ui.toast(t('mods.exported'), mod.fileName || '', 'success', 'download');
    } catch (_) {
      SL.ui.toast(t('mods.exportUnavailable'), '', 'warning', 'warning');
    }
  }

  function updateCounts() {
    const mods = SL.store.mods;
    const installed = mods.length;
    const countEls = ['tab-installed-count', 'mods-installed-count', 'footer-mod-count', 'settings-mod-count'];
    countEls.forEach(function (id) {
      const node = $id(id);
      if (node) node.textContent = String(installed);
    });
    const storage = $id('settings-storage');
    if (storage) storage.textContent = SL.store.formatBytes(SL.store.totalBytes());
    const profile = $id('settings-profile');
    if (profile) profile.textContent = SL.store.themeName();
    const active = SL.store.themeMod();
    const home = $id('home-active-mod');
    const meta = $id('home-mod-meta');
    if (home) home.textContent = active ? active.name : t('home.noMods');
    if (meta) meta.textContent = active ? kindLabel(active.kind) + ' · ' + (active.source === 'gamebanana' ? 'GAMEBANANA' : active.source === 'demo' ? 'DEMO' : 'LOCAL') : 'VANILLA PROFILE';
    const hud = $id('hud-mod');
    const chip = $id('game-mod-chip');
    if (hud) hud.textContent = active ? active.name : 'VANILLA';
    if (chip) chip.textContent = active ? active.name : 'VANILLA';
    const total = $id('mods-total');
    if (total) total.textContent = SL.store.formatNumber(state.total);
    const community = $id('community-count');
    if (community) community.textContent = SL.store.formatNumber(state.total);
  }

  function renderAll() {
    renderBrowse();
    renderInstalled();
    updateCounts();
    updateFilters();
  }

  function updateFilters() {
    document.querySelectorAll('[data-filter]').forEach(function (btn) {
      btn.classList.toggle('is-active', btn.getAttribute('data-filter') === state.category);
    });
    const search = $id('mod-search');
    if (search && search.value !== state.query) search.value = state.query;
    const sort = $id('mod-sort');
    if (sort && sort.value !== state.sort) sort.value = state.sort;
  }

  function setTab(tab) {
    state.tab = tab === 'installed' ? 'installed' : 'browse';
    document.querySelectorAll('[data-mods-tab]').forEach(function (btn) {
      const active = btn.getAttribute('data-mods-tab') === state.tab;
      btn.classList.toggle('is-active', active);
      btn.setAttribute('aria-selected', active ? 'true' : 'false');
    });
    const browse = $id('pane-browse');
    const installed = $id('pane-installed');
    if (browse) browse.classList.toggle('is-active', state.tab === 'browse');
    if (installed) installed.classList.toggle('is-active', state.tab === 'installed');
    if (state.tab === 'installed') renderInstalled();
  }

  /* ── Detail modal ───────────────────────────────────────── */

  function modalShell(mod) {
    const root = el('div', 'mod-detail');
    const hero = el('div', 'modal-hero');
    if (mod.thumb) {
      const img = document.createElement('img');
      img.src = mod.thumb;
      img.alt = '';
      img.referrerPolicy = 'no-referrer';
      img.onerror = function () { img.remove(); hero.classList.add('is-broken'); };
      hero.appendChild(img);
    }
    const fallback = el('span', 'thumb-fallback');
    fallback.appendChild(icon('spark'));
    hero.appendChild(fallback);
    const head = el('div', 'modal-head');
    const kicker = el('div', 'modal-kicker');
    append(kicker, icon('cube'), el('span', '', 'GAMEBANANA · #' + mod.id));
    const h = el('h2', '', mod.name);
    const meta = el('div', 'modal-meta');
    const author = el('span', '', t('mods.by', { author: mod.author }));
    const cat = el('span', '', categoryLabel(mod.category));
    const ver = el('span', '', (mod.version ? t('mods.version') + ' ' + mod.version : ''));
    const views = el('span');
    append(views, icon('eye'), document.createTextNode(SL.store.formatNumber(mod.views) + ' ' + t('mods.views')));
    const likes = el('span');
    append(likes, icon('heart'), document.createTextNode(SL.store.formatNumber(mod.likes) + ' ' + t('mods.likes')));
    append(meta, author, cat, ver, views, likes);
    append(head, kicker, h, meta);
    const content = el('div', 'modal-content');
    append(root, hero, head, content);
    return { root: root, content: content, hero: hero, head: head };
  }

  async function openDetail(id) {
    const mod = state.catalog.find(function (m) { return m.id === Number(id); });
    if (!mod) return;
    state.detail = mod;
    state.detailFiles = [];
    if (SL.audio) SL.audio.sfx('confirm');
    const shell = modalShell(mod);
    const loading = el('div', 'modal-loading');
    loading.appendChild(icon('heart', 'loader-heart'));
    loading.appendChild(el('span', '', t('common.loading')));
    shell.content.appendChild(loading);
    SL.ui.openModal(shell.root, { label: mod.name });
    try {
      const detail = await fetchDetail(mod.id);
      state.detail = Object.assign({}, mod, detail);
      state.detailFiles = detail.files || [];
      renderDetail(shell, state.detail);
    } catch (err) {
      renderDetail(shell, Object.assign({}, mod, { description: '', files: [] }), true);
      SL.ui.toast(t('mods.detailError'), '', 'warning', 'warning');
    }
  }

  function renderDetail(shell, mod, failed) {
    const content = shell.content;
    content.textContent = '';
    const desc = el('div', 'modal-desc', mod.description || t('mods.descMissing'));
    content.appendChild(desc);

    if (mod.screenshots && mod.screenshots.length > 1) {
      const strip = el('div', 'modal-screens');
      mod.screenshots.slice(0, 3).forEach(function (src) {
        const img = document.createElement('img');
        img.src = src;
        img.alt = '';
        img.loading = 'lazy';
        img.referrerPolicy = 'no-referrer';
        img.onclick = function () { window.open(src, '_blank', 'noopener'); };
        strip.appendChild(img);
      });
      content.appendChild(strip);
    }

    const title = el('div', 'modal-section-title');
    append(title, icon('file'), el('span', '', failed ? t('mods.filesError') : t('mods.files')));
    content.appendChild(title);

    const files = (mod.files || []).slice().sort(function (a, b) {
      if (a.archived !== b.archived) return a.archived ? 1 : -1;
      return (b.size || 0) - (a.size || 0);
    }).slice(0, 6);

    if (!files.length) {
      const empty = el('div', 'modal-hint', failed ? t('mods.detailError') : t('mods.filesError'));
      content.appendChild(empty);
    } else {
      files.forEach(function (file) {
        content.appendChild(fileRow(mod, file));
      });
    }

    const actions = el('div', 'modal-actions');
    if (files.length) {
      const latest = files.find(function (f) { return !f.archived; }) || files[0];
      const btn = el('button', 'pixel-button primary');
      btn.type = 'button';
      append(btn, icon('download'), el('span', '', isInstalled(mod.id) ? t('mods.installedState') : t('common.install')));
      btn.addEventListener('click', function () {
        if (btn.disabled) return;
        installGameBanana(mod, latest, btn);
      });
      actions.appendChild(btn);
    }
    const link = document.createElement('a');
    link.className = 'pixel-button';
    link.href = mod.url || ('https://gamebanana.com/mods/' + mod.id);
    link.target = '_blank';
    link.rel = 'noopener noreferrer';
    append(link, icon('external'), el('span', '', t('mods.openFile')));
    actions.appendChild(link);
    const spacer = el('span', 'modal-spacer');
    actions.appendChild(spacer);
    content.appendChild(actions);
    const hint = el('p', 'modal-hint', t('mods.installedInfo') + ' ' + (failed ? t('mods.detailError') : t('legal.modCredit')));
    content.appendChild(hint);
  }

  function fileRow(mod, file) {
    const row = el('div', 'file-row');
    const info = el('div');
    const name = el('div', 'file-name', file.name);
    const meta = el('div', 'file-meta');
    meta.appendChild(el('span', '', SL.store.formatBytes(file.size)));
    if (file.version) meta.appendChild(el('span', '', 'v' + file.version.replace(/^v/i, '')));
    if (file.archived) meta.appendChild(el('span', '', t('mods.archived')));
    if (file.safe) meta.appendChild(el('span', 'ok', '✓ scanned'));
    append(info, name, meta);
    const actions = el('div', 'file-actions');
    const btn = el('button', 'pixel-button small');
    btn.type = 'button';
    append(btn, icon('download'), el('span', '', isInstalled(mod.id) ? t('mods.installedState') : t('mods.install')));
    btn.addEventListener('click', function () {
      if (btn.disabled) return;
      installGameBanana(mod, file, btn, row);
    });
    actions.appendChild(btn);
    const progress = el('div', 'progress-line');
    progress.appendChild(el('i'));
    append(row, info, actions, progress);
    return row;
  }

  function setBusyUi(disabled) {
    document.querySelectorAll('.modal .pixel-button, .modal .file-actions button').forEach(function (btn) {
      if (btn.dataset.keepEnabled === '1') return;
      btn.disabled = !!disabled;
    });
  }

  async function installGameBanana(mod, file, btn, row) {
    if (state.busy) return;
    state.busy = true;
    setBusyUi(true);
    if (btn) {
      btn.disabled = true;
      const label = btn.querySelector('span');
      if (label) label.textContent = t('common.installing');
    }
    const progress = row ? row.querySelector('.progress-line i') : null;
    try {
      if (file.size > MAX_FILE) throw new Error(t('mods.fileTooBig'));
      const blob = await downloadBlob(file.url, function (received, total) {
        if (progress) {
          if (total) progress.style.width = Math.min(100, (received / total) * 100) + '%';
          else progress.style.width = Math.min(92, (received / (file.size || MAX_FILE)) * 100) + '%';
          const label = row ? row.querySelector('.file-meta') : null;
          if (label) {
            let status = label.querySelector('.dl-status');
            if (!status) { status = el('span', 'dl-status'); label.appendChild(status); }
            status.textContent = t('mods.downloading') + ' ' + SL.store.formatBytes(received);
          }
        }
      });
      if (progress) progress.style.width = '100%';
      const record = await installBlob(blob, {
        gbId: mod.id,
        name: mod.name,
        author: mod.author,
        source: 'gamebanana',
        sourceUrl: mod.url,
        thumbnail: mod.thumb,
        category: mod.category,
        version: mod.version || file.version,
        fileName: file.name,
        description: mod.description || '',
        screenshots: mod.screenshots || [],
        downloadUrl: file.url
      });
      SL.audio.sfx('install');
      SL.ui.toast(t('mods.installSuccess', { name: record.name }), t('mods.installSuccessSub'), 'success', 'check');
      if (btn) {
        const label = btn.querySelector('span');
        if (label) label.textContent = t('mods.installedState');
      }
      renderAll();
      if (state.tab !== 'installed') setTab('installed');
    } catch (err) {
      if (window.console) console.warn('[SOUL LINK] install:', err);
      SL.audio.sfx('error');
      SL.ui.toast(t('mods.installError'), (err && err.message) || t('mods.downloadFailed'), 'error', 'warning');
    } finally {
      state.busy = false;
      setBusyUi(false);
      if (btn) btn.disabled = false;
    }
  }

  async function downloadBlob(url, onProgress) {
    const res = await fetch(url, { mode: 'cors', credentials: 'omit' });
    if (!res.ok) throw new Error('HTTP ' + res.status);
    const total = Number(res.headers.get('content-length')) || 0;
    if (!res.body || !res.body.getReader) {
      const blob = await res.blob();
      if (onProgress) onProgress(blob.size, blob.size);
      return blob;
    }
    const reader = res.body.getReader();
    const chunks = [];
    let received = 0;
    while (true) {
      const step = await reader.read();
      if (step.done) break;
      if (step.value) {
        chunks.push(step.value);
        received += step.value.byteLength;
        if (onProgress) onProgress(received, total);
      }
    }
    return new Blob(chunks, { type: res.headers.get('content-type') || 'application/octet-stream' });
  }

  /* ── Installing files ───────────────────────────────────── */

  async function installBlob(blob, meta) {
    if (!blob) throw new Error(t('mods.invalidFile'));
    if (blob.size > MAX_FILE) throw new Error(t('mods.fileTooBig'));
    const fileName = meta.fileName || meta.name || 'mod.bin';
    const ext = (fileName.split('.').pop() || '').toLowerCase();
    let target = blob;
    let kind = 'archive';
    let storedName = fileName;
    let validDataWin = false;
    let warning = '';

    const looksZip = ext === 'zip' || (blob.size > 4 && await isZip(blob));
    if (looksZip) {
      if (typeof JSZip === 'undefined') throw new Error('ZIP support is not loaded');
      const zip = await JSZip.loadAsync(blob);
      const names = Object.keys(zip.files);
      const winNames = names.filter(function (n) { return /(^|\/)(data|game)\.win$/i.test(n) || /\.win$/i.test(n); });
      const patchNames = names.filter(function (n) { return /\.(xdelta|patch|bps)$/i.test(n); });
      if (winNames.length) {
        const pick = winNames.find(function (n) { return /(^|\/)data\.win$/i.test(n); }) || winNames[0];
        target = await zip.file(pick).async('blob');
        storedName = pick.split('/').pop();
        kind = 'datawin';
      } else if (patchNames.length) {
        target = await zip.file(patchNames[0]).async('blob');
        storedName = patchNames[0].split('/').pop();
        kind = 'patch';
        warning = t('mods.zipNoWin');
      } else {
        warning = t('mods.zipNoWin');
      }
    } else if (ext === 'win' || ext === 'datawin' || (await isForm(blob))) {
      kind = 'datawin';
      storedName = fileName;
    } else if (ext === 'xdelta' || ext === 'patch' || ext === 'bps') {
      kind = 'patch';
      storedName = fileName;
    }

    if (kind === 'datawin') {
      const check = await SL.store.inspectDataWin(target);
      validDataWin = check.valid;
    }
    const hash = await SL.store.blobHash(target);
    const id = meta.source === 'gamebanana' && meta.gbId ? 'gb-' + meta.gbId : 'local-' + hash;
    await SL.store.putFile(id, target);
    const paletteIndex = SL.store.derivePaletteIndex(id + ':' + fileName + ':' + hash);
    const record = {
      id: id,
      gbId: meta.source === 'gamebanana' ? meta.gbId : null,
      name: meta.name || storedName.replace(/\.(win|zip|xdelta|patch|bps)$/i, ''),
      author: meta.author || t('mods.sourceLocal'),
      source: meta.source || 'local',
      sourceUrl: meta.sourceUrl || '',
      thumbnail: meta.thumbnail || '',
      category: meta.category || '',
      version: meta.version || '',
      description: meta.description || '',
      screenshots: meta.screenshots || [],
      installDate: Date.now(),
      activatedAt: Date.now(),
      active: true,
      size: target.size,
      kind: kind,
      fileName: storedName,
      blobId: id,
      hash: hash,
      validDataWin: validDataWin,
      paletteIndex: paletteIndex
    };
    SL.store.addMod(record);
    if (warning) SL.ui.toast(warning, '', 'warning', 'warning');
    return record;
  }

  async function isZip(blob) {
    try {
      const head = new Uint8Array(await blob.slice(0, 4).arrayBuffer());
      return head[0] === 0x50 && head[1] === 0x4b;
    } catch (_) { return false; }
  }
  async function isForm(blob) {
    try {
      const head = new Uint8Array(await blob.slice(0, 4).arrayBuffer());
      return head[0] === 0x46 && head[1] === 0x4f && head[2] === 0x52 && head[3] === 0x4d;
    } catch (_) { return false; }
  }

  async function installLocalFile(file) {
    if (!file) return;
    if (file.size > MAX_FILE) { SL.ui.toast(t('mods.installError'), t('mods.fileTooBig'), 'error', 'warning'); return; }
    const ext = (file.name.split('.').pop() || '').toLowerCase();
    if (['win', 'datawin', 'zip', 'xdelta', 'patch', 'bps'].indexOf(ext) < 0) {
      SL.ui.toast(t('mods.invalidFile'), file.name, 'warning', 'warning');
      return;
    }
    SL.ui.toast(t('common.installing'), file.name, 'info', 'download');
    try {
      const record = await installBlob(file, {
        name: file.name.replace(/\.(win|zip|xdelta|patch|bps)$/i, ''),
        author: t('mods.sourceLocal'),
        source: 'local',
        fileName: file.name
      });
      SL.audio.sfx('install');
      SL.ui.toast(t('mods.installSuccess', { name: record.name }), t('mods.installSuccessSub'), 'success', 'check');
      renderAll();
      setTab('installed');
    } catch (err) {
      if (window.console) console.warn('[SOUL LINK] local install:', err);
      SL.audio.sfx('error');
      SL.ui.toast(t('mods.installError'), (err && err.message) || t('mods.invalidFile'), 'error', 'warning');
    }
  }

  function installDemo() {
    const existing = SL.store.mods.find(function (m) { return m.id === 'demo-golden-bloom'; });
    if (existing) {
      SL.store.setActive(existing.id, true);
      SL.ui.toast(t('mods.activated', { name: existing.name }), '', 'success', 'spark');
      renderAll();
      return;
    }
    const paletteIndex = SL.data.PALETTES.findIndex(function (p) { return p.id === 'golden-bloom'; });
    SL.store.addMod({
      id: 'demo-golden-bloom',
      name: t('mods.demoName'),
      author: t('mods.demoAuthor'),
      source: 'demo',
      sourceUrl: '',
      thumbnail: '',
      category: 'themes',
      version: '1.0',
      description: t('mods.demoDesc'),
      screenshots: [],
      installDate: Date.now(),
      activatedAt: Date.now(),
      active: true,
      size: 0,
      kind: 'theme',
      fileName: '',
      blobId: '',
      hash: 'demo',
      validDataWin: false,
      paletteIndex: paletteIndex >= 0 ? paletteIndex : 2
    });
    SL.audio.sfx('install');
    SL.ui.toast(t('mods.installSuccess', { name: t('mods.demoName') }), t('mods.installSuccessSub'), 'success', 'spark');
    renderAll();
    setTab('installed');
  }

  /* ── Boot / public ───────────────────────────────────────── */

  function init() {
    state.catalog = SL.data.FALLBACK_MODS.map(function (m) { return Object.assign({}, m); });
    chooseFeatured();
    renderAll();
    setTab('browse');
    setApiStatus('loading');
    loadFeed(1, false);
    window.addEventListener('online', function () {
      if (!state.live) loadFeed(1, false);
    });
  }

  function refreshLanguage() {
    setApiStatus(state.live === false ? 'offline' : state.live ? 'online' : 'loading');
    updateFeatured();
    renderAll();
    if (state.detail) {
      // Re-render an open detail modal without re-fetching.
      const shell = document.querySelector('.mod-detail');
      if (shell && shell.__soulDetail) renderDetail(shell.__soulDetail, state.detail, false);
    }
  }

  function setQuery(value) {
    state.query = value || '';
    renderBrowse();
  }
  function setCategory(value) {
    state.category = value || 'all';
    renderBrowse();
    updateFilters();
  }
  function setSort(value) {
    state.sort = value || 'featured';
    renderBrowse();
  }
  function loadMore() {
    if (state.loading || !state.hasMore) return;
    const btn = $id('load-more-btn');
    if (btn) btn.disabled = true;
    loadFeed(state.page + 1, true).finally(function () {
      if (btn) btn.disabled = false;
    });
  }

  window.SL = window.SL || {};
  SL.mods = {
    init: init,
    renderAll: renderAll,
    renderInstalled: renderInstalled,
    refreshLanguage: refreshLanguage,
    openDetail: openDetail,
    openFeatured: function () { if (state.featured) openDetail(state.featured.id); },
    installDemo: installDemo,
    installLocalFile: installLocalFile,
    setTab: setTab,
    setQuery: setQuery,
    setCategory: setCategory,
    setSort: setSort,
    loadMore: loadMore,
    updateCounts: updateCounts,
    get featured() { return state.featured; },
    get catalog() { return state.catalog.slice(); },
    get live() { return state.live; },
    get total() { return state.total; }
  };
})();

/* SOUL LINK — launcher shell, routing, settings, input and ambient world. */
(function () {
  'use strict';

  const t = function (key, vars) { return SL.i18n.t(key, vars); };
  const $ = function (id) { return document.getElementById(id); };
  const $$ = function (selector, root) { return Array.from((root || document).querySelectorAll(selector)); };

  const appState = {
    view: 'home',
    booted: false,
    gameMounted: false,
    modalOpen: false,
    modalResolve: null,
    lastFocus: null,
    dragDepth: 0,
    searchTimer: null,
    apkBytes: 0,
    clockTimer: null
  };

  const isTouch = ('ontouchstart' in window) || (navigator.maxTouchPoints > 0) || window.matchMedia('(pointer: coarse)').matches;
  const isAndroidApp = /SoulLinkAndroid/i.test(navigator.userAgent);

  /* ── Toast ───────────────────────────────────────────────── */

  function toast(title, message, type, iconName) {
    const region = $('toast-region');
    if (!region) return;
    const node = document.createElement('div');
    node.className = 'toast' + (type ? ' is-' + type : '');
    const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
    svg.setAttribute('class', 'icon');
    svg.setAttribute('aria-hidden', 'true');
    const use = document.createElementNS('http://www.w3.org/2000/svg', 'use');
    use.setAttribute('href', '#i-' + (iconName || (type === 'success' ? 'check' : type === 'error' || type === 'warning' ? 'warning' : 'spark')));
    svg.appendChild(use);
    const copy = document.createElement('div');
    const strong = document.createElement('strong');
    strong.textContent = title || '';
    copy.appendChild(strong);
    if (message) {
      const span = document.createElement('span');
      span.textContent = message;
      copy.appendChild(span);
    }
    node.appendChild(svg);
    node.appendChild(copy);
    region.appendChild(node);
    while (region.children.length > 4) region.removeChild(region.firstElementChild);
    const remove = function () {
      if (!node.parentNode) return;
      node.classList.add('is-out');
      setTimeout(function () { if (node.parentNode) node.remove(); }, 240);
    };
    node.addEventListener('click', remove);
    setTimeout(remove, type === 'error' ? 6200 : 4200);
  }

  /* ── Modal ───────────────────────────────────────────────── */

  function openModal(content, options) {
    const layer = $('modal-layer');
    const body = $('modal-body');
    if (!layer || !body) return;
    appState.lastFocus = document.activeElement;
    appState.modalOpen = true;
    if (appState.modalResolve) { appState.modalResolve(false); appState.modalResolve = null; }
    body.textContent = '';
    if (typeof content === 'string') {
      const wrapper = document.createElement('div');
      wrapper.textContent = content;
      body.appendChild(wrapper);
    } else {
      body.appendChild(content);
    }
    const dialog = layer.querySelector('.modal');
    if (dialog) dialog.setAttribute('aria-label', (options && options.label) || '');
    layer.hidden = false;
    document.body.classList.add('modal-open');
    const close = layer.querySelector('.modal-close');
    if (close) {
      close.setAttribute('aria-label', t('modal.close'));
      setTimeout(function () { close.focus(); }, 30);
    }
    document.addEventListener('keydown', modalKeydown, true);
  }

  function closeModal(result) {
    const layer = $('modal-layer');
    if (!layer || layer.hidden) {
      if (appState.modalResolve) {
        const r = appState.modalResolve;
        appState.modalResolve = null;
        r(false);
      }
      return;
    }
    layer.hidden = true;
    appState.modalOpen = false;
    document.body.classList.remove('modal-open');
    document.removeEventListener('keydown', modalKeydown, true);
    const body = $('modal-body');
    if (body) body.textContent = '';
    if (appState.modalResolve) {
      const resolve = appState.modalResolve;
      appState.modalResolve = null;
      resolve(result === true);
    }
    if (appState.lastFocus && typeof appState.lastFocus.focus === 'function') {
      try { appState.lastFocus.focus(); } catch (_) {}
    }
    appState.lastFocus = null;
  }

  function modalKeydown(e) {
    if (!appState.modalOpen) return;
    if (e.key === 'Escape') {
      e.preventDefault();
      closeModal(false);
      return;
    }
    if (e.key !== 'Tab') return;
    const layer = $('modal-layer');
    if (!layer) return;
    const focusables = $$('button:not([disabled]), a[href], input:not([disabled]), select:not([disabled]), [tabindex]:not([tabindex="-1"])', layer)
      .filter(function (node) { return node.offsetParent !== null; });
    if (!focusables.length) return;
    const first = focusables[0];
    const last = focusables[focusables.length - 1];
    if (e.shiftKey && document.activeElement === first) {
      e.preventDefault();
      last.focus();
    } else if (!e.shiftKey && document.activeElement === last) {
      e.preventDefault();
      first.focus();
    }
  }

  function confirmDialog(opts) {
    const box = document.createElement('div');
    box.className = 'confirm-box';
    const icon = document.createElement('div');
    icon.className = 'confirm-icon';
    icon.innerHTML = '<svg class="icon" aria-hidden="true"><use href="#i-' + (opts.icon || 'warning') + '"></use></svg>';
    const h = document.createElement('h2');
    h.textContent = opts.title || '';
    const p = document.createElement('p');
    p.textContent = opts.copy || '';
    const actions = document.createElement('div');
    actions.className = 'confirm-actions';
    const cancel = document.createElement('button');
    cancel.className = 'pixel-button ghost';
    cancel.type = 'button';
    cancel.textContent = opts.cancelText || t('common.cancel');
    const ok = document.createElement('button');
    ok.className = 'pixel-button ' + (opts.danger ? 'danger' : 'primary');
    ok.type = 'button';
    ok.textContent = opts.confirmText || t('common.confirm');
    actions.appendChild(cancel);
    actions.appendChild(ok);
    box.appendChild(icon);
    box.appendChild(h);
    box.appendChild(p);
    box.appendChild(actions);
    openModal(box, { label: opts.title });
    return new Promise(function (resolve) {
      appState.modalResolve = resolve;
      cancel.addEventListener('click', function () { closeModal(false); });
      ok.addEventListener('click', function () { closeModal(true); });
      setTimeout(function () { ok.focus(); }, 40);
    });
  }

  /* ── Routing ─────────────────────────────────────────────── */

  function navigate(view, options) {
    const target = ['home', 'game', 'settings', 'mods'].indexOf(view) >= 0 ? view : 'home';
    if (appState.modalOpen) closeModal(false);
    if (appState.view === 'game' && target !== 'game') stopGame();
    appState.view = target;
    $$('.view').forEach(function (section) {
      const active = section.getAttribute('data-view') === target;
      section.hidden = !active;
      section.classList.toggle('is-active', active);
    });
    document.body.classList.toggle('is-playing', target === 'game');
    document.body.classList.remove('modal-open');
    const stage = $('main-stage');
    if (stage) stage.scrollTop = 0;
    window.scrollTo(0, 0);
    if (target === 'game') startGame();
    if (target === 'settings') refreshSettingsUI();
    if (target === 'mods') {
      if (options && options.tab) SL.mods.setTab(options.tab);
      SL.mods.updateCounts();
    }
    if (target !== 'game') {
      const heading = document.querySelector('#view-' + target + ' h1, #view-' + target + ' h2');
      if (heading) {
        heading.setAttribute('tabindex', '-1');
        setTimeout(function () { try { heading.focus({ preventScroll: true }); } catch (_) {} }, 60);
      }
    }
    setStatus(target === 'home' ? t('footer.ready') : target === 'mods' ? 'GAMEBANANA // 5506' : target === 'settings' ? 'SYSTEM CONFIG' : 'THE SEAM');
    try {
      if (location.protocol !== 'file:') history.replaceState(null, '', '#' + target);
    } catch (_) {}
  }

  function startGame() {
    const canvas = $('game-canvas');
    if (!canvas) return;
    if (!appState.gameMounted) {
      SL.game.mount(canvas);
      appState.gameMounted = true;
    }
    document.body.classList.add('is-playing');
    SL.game.start();
    try { canvas.focus({ preventScroll: true }); } catch (_) {}
    updateGameChrome();
  }

  function stopGame() {
    if (appState.gameMounted) SL.game.stop();
    document.body.classList.remove('is-playing');
    SL.game.clearKeys();
    document.querySelectorAll('.dpad-btn.is-pressed, .round-btn.is-pressed').forEach(function (b) { b.classList.remove('is-pressed'); });
  }

  function updateGameChrome() {
    const active = SL.store.themeMod();
    const name = active ? active.name : 'VANILLA';
    const hud = $('hud-mod');
    const chip = $('game-mod-chip');
    if (hud) hud.textContent = name;
    if (chip) chip.textContent = name;
  }

  /* ── Settings ────────────────────────────────────────────── */

  function refreshSettingsUI() {
    const s = SL.store.settings;
    setRange('master-volume', 'master-volume-out', s.master);
    setRange('music-volume', 'music-volume-out', s.music);
    setRange('sfx-volume', 'sfx-volume-out', s.sfx);
    $$('[data-setting]').forEach(function (btn) {
      const key = btn.getAttribute('data-setting');
      const value = !!s[key];
      btn.setAttribute('aria-checked', value ? 'true' : 'false');
    });
    const lang = SL.i18n.lang;
    $$('#language-switch [data-lang]').forEach(function (btn) {
      btn.classList.toggle('is-active', btn.getAttribute('data-lang') === lang);
      btn.setAttribute('aria-pressed', btn.getAttribute('data-lang') === lang ? 'true' : 'false');
    });
    const count = $('settings-mod-count');
    if (count) count.textContent = String(SL.store.mods.length);
    const storage = $('settings-storage');
    if (storage) storage.textContent = SL.store.formatBytes(SL.store.totalBytes());
    const profile = $('settings-profile');
    if (profile) {
      profile.textContent = SL.store.themeName();
      profile.classList.toggle('is-accent', !!SL.store.themeMod());
    }
    syncSound();
  }

  function setRange(inputId, outputId, value) {
    const input = $(inputId);
    const out = $(outputId);
    if (input) {
      input.value = String(value);
      input.style.setProperty('--fill', value + '%');
    }
    if (out) out.textContent = String(value);
  }

  function syncSound() {
    const muted = SL.store.settings.muted;
    document.body.classList.toggle('is-muted', muted);
    const btn = $('sound-toggle');
    if (btn) btn.setAttribute('aria-pressed', muted ? 'false' : 'true');
  }

  function applyAudioSettings() {
    const s = SL.store.settings;
    SL.audio.setVolumes({ master: s.master, music: s.music, sfx: s.sfx, muted: s.muted });
  }

  /* ── Mods view wiring ────────────────────────────────────── */

  function wireMods() {
    $$('[data-mods-tab]').forEach(function (btn) {
      btn.addEventListener('click', function () {
        SL.mods.setTab(btn.getAttribute('data-mods-tab'));
        if (SL.audio) SL.audio.sfx('move');
      });
    });
    const search = $('mod-search');
    if (search) {
      search.addEventListener('input', function () {
        if (appState.searchTimer) clearTimeout(appState.searchTimer);
        appState.searchTimer = setTimeout(function () { SL.mods.setQuery(search.value); }, 130);
      });
    }
    const sort = $('mod-sort');
    if (sort) sort.addEventListener('change', function () { SL.mods.setSort(sort.value); });
    $$('[data-filter]').forEach(function (btn) {
      btn.addEventListener('click', function () {
        SL.mods.setCategory(btn.getAttribute('data-filter'));
        if (SL.audio) SL.audio.sfx('move');
      });
    });
    const drop = $('import-panel');
    const dropOverlay = $('drop-overlay');
    const view = $('view-mods');
    if (view) {
      ['dragenter', 'dragover'].forEach(function (event) {
        view.addEventListener(event, function (e) {
          if (!e.dataTransfer || Array.prototype.indexOf.call(e.dataTransfer.types || [], 'Files') < 0) return;
          e.preventDefault();
          appState.dragDepth += 1;
          if (drop) drop.classList.add('is-drag');
          if (dropOverlay) dropOverlay.hidden = false;
        });
      });
      ['dragleave', 'drop'].forEach(function (event) {
        view.addEventListener(event, function (e) {
          if (event === 'drop') e.preventDefault();
          appState.dragDepth = Math.max(0, appState.dragDepth - 1);
          if (appState.dragDepth === 0) {
            if (drop) drop.classList.remove('is-drag');
            if (dropOverlay) dropOverlay.hidden = true;
          }
          if (event === 'drop') {
            const files = e.dataTransfer && e.dataTransfer.files;
            if (files && files.length) SL.mods.installLocalFile(files[0]);
          }
        });
      });
    }
  }

  /* ── Actions ─────────────────────────────────────────────── */

  function handleAction(action) {
    switch (action) {
      case 'go-home':
        if (SL.audio) SL.audio.sfx('back');
        stopGame();
        navigate('home');
        break;
      case 'new-game':
        if (SL.audio) SL.audio.sfx('confirm');
        navigate('game');
        break;
      case 'open-settings':
        if (SL.audio) SL.audio.sfx('confirm');
        stopGame();
        navigate('settings');
        break;
      case 'open-mods':
        if (SL.audio) SL.audio.sfx('confirm');
        stopGame();
        navigate('mods');
        break;
      case 'sound-toggle': {
        const next = !SL.store.settings.muted;
        SL.store.saveSettings({ muted: next });
        if (SL.audio) {
          SL.audio.setMuted(next);
          if (!next) { SL.audio.unlock(); SL.audio.sfx('confirm'); }
        }
        syncSound();
        toast(next ? t('settings.mute') : t('common.ready'), '', next ? 'warning' : 'success', next ? 'sound-off' : 'sound-on');
        break;
      }
      case 'fullscreen': {
        toggleFullscreen();
        break;
      }
      case 'featured-open':
        SL.mods.openFeatured();
        break;
      case 'import-file': {
        const input = $('mod-file-input');
        if (input) input.click();
        break;
      }
      case 'install-demo':
        SL.mods.installDemo();
        break;
      case 'load-more':
        SL.mods.loadMore();
        break;
      case 'clear-filters':
        SL.mods.setQuery('');
        SL.mods.setCategory('all');
        const search = $('mod-search');
        if (search) search.value = '';
        break;
      case 'browse-mods':
        SL.mods.setTab('browse');
        break;
      case 'reset-data':
        confirmDialog({
          title: t('settings.resetTitle'),
          copy: t('settings.resetCopy'),
          confirmText: t('settings.resetConfirm'),
          cancelText: t('common.cancel'),
          danger: true,
          icon: 'trash'
        }).then(function (ok) {
          if (!ok) return;
          SL.store.resetAll().then(function () {
            refreshSettingsUI();
            SL.mods.renderAll();
            SL.i18n.apply(document);
            if (SL.audio) SL.audio.sfx('delete');
            toast(t('settings.resetDone'), '', 'success', 'check');
            navigate('home');
          });
        });
        break;
      case 'pause':
        if (SL.game.isRunning() && !SL.game.isPaused()) SL.game.pause();
        break;
      case 'resume':
        SL.game.resume();
        break;
      case 'pause-settings':
        stopGame();
        navigate('settings');
        break;
      case 'game-menu':
        stopGame();
        navigate('home');
        break;
      case 'retry':
        SL.game.retry();
        break;
      case 'replay':
        SL.game.retry();
        break;
      default:
        break;
    }
  }

  function toggleFullscreen() {
    const root = document.documentElement;
    try {
      if (!document.fullscreenElement) {
        if (root.requestFullscreen) root.requestFullscreen();
        else if (root.webkitRequestFullscreen) root.webkitRequestFullscreen();
      } else {
        if (document.exitFullscreen) document.exitFullscreen();
        else if (document.webkitExitFullscreen) document.webkitExitFullscreen();
      }
    } catch (_) {}
  }

  /* ── Input ───────────────────────────────────────────────── */

  function isEditable(target) {
    if (!target) return false;
    const tag = target.tagName;
    return tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT' || target.isContentEditable;
  }

  function menuItems() { return $$('#main-menu .menu-item'); }

  function moveMenuFocus(delta) {
    const items = menuItems();
    if (!items.length) return;
    const index = items.indexOf(document.activeElement);
    let next = index < 0 ? (delta > 0 ? 0 : items.length - 1) : index + delta;
    if (next < 0) next = items.length - 1;
    if (next >= items.length) next = 0;
    items[next].focus();
    items[next].classList.add('is-bump');
    setTimeout(function () { items[next].classList.remove('is-bump'); }, 180);
    if (SL.audio) SL.audio.sfx('move');
  }

  function keydown(e) {
    if (appState.modalOpen) return;
    const target = e.target;
    if (isEditable(target)) {
      if (e.key === 'Escape') { target.blur(); }
      return;
    }
    const key = e.key;
    if (appState.view === 'game') {
      const map = {
        ArrowUp: 'up', ArrowDown: 'down', ArrowLeft: 'left', ArrowRight: 'right',
        w: 'up', W: 'up', s: 'down', S: 'down', a: 'left', A: 'left', d: 'right', D: 'right'
      };
      if (map[key]) {
        e.preventDefault();
        SL.game.setDirection(map[key], true);
        return;
      }
      if (key === 'Enter' || key === ' ' || key === 'z' || key === 'Z') {
        e.preventDefault();
        if (!e.repeat) SL.game.action();
        return;
      }
      if (key === 'Escape' || key === 'x' || key === 'X' || key === 'Backspace') {
        e.preventDefault();
        if (SL.game.mode() === 'dead' || SL.game.mode() === 'complete') return;
        SL.game.cancel();
        return;
      }
      return;
    }

    if (key === 'Escape') {
      if (appState.view !== 'home') {
        e.preventDefault();
        if (SL.audio) SL.audio.sfx('back');
        navigate('home');
      }
      return;
    }
    if (appState.view === 'mods' && key === '/') {
      const search = $('mod-search');
      if (search) { e.preventDefault(); search.focus(); search.select(); }
      return;
    }
    if (appState.view === 'home') {
      if (key === 'ArrowDown' || key === 'ArrowUp') {
        e.preventDefault();
        moveMenuFocus(key === 'ArrowDown' ? 1 : -1);
        return;
      }
      if (key === 'Enter' || key === ' ') {
        const active = document.activeElement;
        if (active && active.classList.contains('menu-item')) {
          e.preventDefault();
          active.click();
        } else if (menuItems()[0]) {
          e.preventDefault();
          menuItems()[0].click();
        }
        return;
      }
      if (key === 'm' || key === 'M') { handleAction('open-mods'); return; }
      if (key === 's' || key === 'S') { handleAction('open-settings'); return; }
      if (key === 'n' || key === 'N') { handleAction('new-game'); return; }
      if (key === 'f' || key === 'F') { toggleFullscreen(); return; }
    }
  }

  function keyup(e) {
    if (appState.view !== 'game') return;
    const map = {
      ArrowUp: 'up', ArrowDown: 'down', ArrowLeft: 'left', ArrowRight: 'right',
      w: 'up', W: 'up', s: 'down', S: 'down', a: 'left', A: 'left', d: 'right', D: 'right'
    };
    if (map[e.key]) SL.game.setDirection(map[e.key], false);
  }

  function wireTouchControls() {
    $$('.dpad-btn').forEach(function (btn) {
      const dir = btn.getAttribute('data-dir');
      const press = function (e) {
        e.preventDefault();
        try { btn.setPointerCapture(e.pointerId); } catch (_) {}
        btn.classList.add('is-pressed');
        SL.game.setDirection(dir, true);
        vibrate(6);
      };
      const release = function (e) {
        if (e) e.preventDefault();
        btn.classList.remove('is-pressed');
        SL.game.setDirection(dir, false);
      };
      btn.addEventListener('pointerdown', press);
      btn.addEventListener('pointerup', release);
      btn.addEventListener('pointercancel', release);
      btn.addEventListener('lostpointercapture', release);
      btn.addEventListener('contextmenu', function (e) { e.preventDefault(); });
    });
    $$('.round-btn').forEach(function (btn) {
      const kind = btn.getAttribute('data-btn');
      const press = function (e) {
        e.preventDefault();
        btn.classList.add('is-pressed');
        vibrate(10);
        if (kind === 'a') SL.game.action();
        else SL.game.cancel();
      };
      const release = function (e) {
        if (e) e.preventDefault();
        btn.classList.remove('is-pressed');
      };
      btn.addEventListener('pointerdown', press);
      btn.addEventListener('pointerup', release);
      btn.addEventListener('pointercancel', release);
      btn.addEventListener('pointerleave', release);
      btn.addEventListener('contextmenu', function (e) { e.preventDefault(); });
    });
  }

  function vibrate(ms) {
    if (!SL.store.settings.haptics) return;
    if (navigator.vibrate) {
      try { navigator.vibrate(ms); } catch (_) {}
    }
  }

  function wireSettings() {
    $$('[data-setting]').forEach(function (btn) {
      btn.addEventListener('click', function () {
        const key = btn.getAttribute('data-setting');
        const current = !!SL.store.settings[key];
        const next = !current;
        const patch = {};
        patch[key] = next;
        SL.store.saveSettings(patch);
        btn.setAttribute('aria-checked', next ? 'true' : 'false');
        if (SL.audio) {
          if (key === 'muted') SL.audio.setMuted(next);
          else SL.audio.sfx('move');
        }
        if (key === 'muted') syncSound();
        if (key === 'reduceMotion') {
          // keep the ambient canvas consistent with the setting
          restartAmbient();
        }
      });
    });
    [['master-volume', 'master-volume-out', 'master'], ['music-volume', 'music-volume-out', 'music'], ['sfx-volume', 'sfx-volume-out', 'sfx']].forEach(function (spec) {
      const input = $(spec[0]);
      const out = $(spec[1]);
      if (!input) return;
      input.addEventListener('input', function () {
        const value = Number(input.value) || 0;
        if (out) out.textContent = String(value);
        input.style.setProperty('--fill', value + '%');
        const patch = {};
        patch[spec[2]] = value;
        SL.store.saveSettings(patch);
        const s = SL.store.settings;
        SL.audio.setVolumes({ master: s.master, music: s.music, sfx: s.sfx, muted: s.muted });
      });
    });
    const langSwitch = $('language-switch');
    if (langSwitch) {
      langSwitch.addEventListener('click', function (e) {
        const btn = e.target.closest('[data-lang]');
        if (!btn) return;
        const next = btn.getAttribute('data-lang');
        if (SL.i18n.setLang(next)) {
          SL.i18n.apply(document);
          SL.mods.refreshLanguage();
          refreshSettingsUI();
          updateCounts();
          if (SL.audio) SL.audio.sfx('confirm');
          toast(t('settings.languageChanged'), '', 'success', 'globe');
        }
      });
    }
  }

  /* ── Ambient background ──────────────────────────────────── */

  let ambient = null;

  function initAmbient() {
    const canvas = $('ambient-canvas');
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    const particles = [];
    const count = 62;
    for (let i = 0; i < count; i++) {
      particles.push({
        x: Math.random(), y: Math.random(),
        size: Math.random() < 0.76 ? 1 : 2,
        speed: 0.006 + Math.random() * 0.02,
        drift: (Math.random() - 0.5) * 0.004,
        alpha: 0.08 + Math.random() * 0.34,
        gold: Math.random() < 0.17,
        phase: Math.random() * Math.PI * 2
      });
    }
    let raf = null;
    let last = 0;
    let w = 0, h = 0, dpr = 1;
    function resize() {
      dpr = Math.min(2, window.devicePixelRatio || 1);
      w = window.innerWidth;
      h = window.innerHeight;
      canvas.width = Math.max(1, Math.floor(w * dpr));
      canvas.height = Math.max(1, Math.floor(h * dpr));
      canvas.style.width = w + 'px';
      canvas.style.height = h + 'px';
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.imageSmoothingEnabled = false;
    }
    function frame(now) {
      if (!last) last = now;
      const dt = Math.min(0.05, (now - last) / 1000);
      last = now;
      raf = requestAnimationFrame(frame);
      const reduce = SL.store.settings.reduceMotion;
      ctx.clearRect(0, 0, w, h);
      const palette = SL.store.currentPalette();
      const accent = (palette && palette.accent) || '#ff3355';
      const gold = (palette && palette.gold) || '#ffd75e';
      // a very faint pixel heart watermark
      ctx.save();
      ctx.globalAlpha = 0.018;
      ctx.fillStyle = accent;
      const scale = Math.max(16, Math.min(30, w / 46));
      const cx = w * 0.76;
      const cy = h * 0.5 + Math.sin(now / 6000) * 10;
      const heart = [
        [4, 0, 2, 1], [10, 0, 2, 1], [3, 1, 4, 1], [9, 1, 4, 1], [2, 2, 12, 1],
        [1, 3, 14, 1], [0, 4, 16, 3], [1, 7, 14, 2], [2, 9, 12, 1], [3, 10, 10, 1],
        [4, 11, 8, 1], [5, 12, 6, 1], [6, 13, 4, 1], [7, 14, 2, 1]
      ];
      heart.forEach(function (r) { ctx.fillRect(cx + (r[0] - 8) * scale, cy + (r[1] - 7) * scale, r[2] * scale, r[3] * scale); });
      ctx.restore();

      particles.forEach(function (p) {
        if (!reduce) {
          p.y -= p.speed * dt * (0.6 + p.size * 0.3);
          p.x += p.drift * dt;
          if (p.y < -0.02) { p.y = 1.02; p.x = Math.random(); }
          if (p.x < -0.02) p.x = 1.02;
          if (p.x > 1.02) p.x = -0.02;
        }
        const twinkle = 0.55 + Math.sin(now / 900 + p.phase) * 0.45;
        ctx.globalAlpha = p.alpha * twinkle;
        ctx.fillStyle = p.gold ? gold : accent;
        ctx.fillRect(Math.floor(p.x * w), Math.floor(p.y * h), p.size, p.size);
        if (p.size === 2) {
          ctx.globalAlpha = p.alpha * twinkle * 0.3;
          ctx.fillRect(Math.floor(p.x * w) - 1, Math.floor(p.y * h) + 2, 4, 1);
        }
      });
      ctx.globalAlpha = 1;
    }
    resize();
    window.addEventListener('resize', resize);
    raf = requestAnimationFrame(frame);
    ambient = {
      stop: function () { if (raf) cancelAnimationFrame(raf); raf = null; window.removeEventListener('resize', resize); },
      restart: function () { if (ambient) ambient.stop(); initAmbient(); }
    };
  }

  function restartAmbient() {
    if (ambient) ambient.restart();
  }

  /* ── APK detection ───────────────────────────────────────── */

  function setupApk() {
    if (isAndroidApp) {
      document.body.classList.add('is-android-app');
      const hide = ['android-badge', 'apk-card', 'settings-apk-link'];
      hide.forEach(function (id) {
        const node = $(id);
        if (node) node.hidden = true;
      });
      return;
    }
    fetch('download/soul-link-launcher.apk', { method: 'HEAD' }).then(function (res) {
      if (!res.ok) {
        document.body.classList.add('no-apk');
        return;
      }
      const size = Number(res.headers.get('content-length')) || 0;
      if (size) {
        appState.apkBytes = size;
        const label = document.querySelector('#settings-apk-link span');
        if (label) label.textContent = t('common.download') + ' APK · ' + SL.store.formatBytes(size);
        const meta = document.querySelector('#apk-card .apk-copy span:last-child');
        if (meta) meta.textContent = t('common.download') + ' · 1.0.0 · ' + SL.store.formatBytes(size);
      }
    }).catch(function () {
      document.body.classList.add('no-apk');
    });
  }

  /* ── Counts / theme chrome ───────────────────────────────── */

  function updateCounts() {
    const count = SL.store.mods.length;
    ['tab-installed-count', 'mods-installed-count', 'footer-mod-count', 'settings-mod-count'].forEach(function (id) {
      const node = $(id);
      if (node) node.textContent = String(count);
    });
    const storage = $('settings-storage');
    if (storage) storage.textContent = SL.store.formatBytes(SL.store.totalBytes());
    const active = SL.store.themeMod();
    const name = active ? active.name : t('home.noMods');
    const homeName = $('home-active-mod');
    const homeMeta = $('home-mod-meta');
    if (homeName) homeName.textContent = name;
    if (homeMeta) homeMeta.textContent = active ? active.source === 'gamebanana' ? 'GAMEBANANA · ACTIVE' : active.source === 'demo' ? 'DEMO THEME · ACTIVE' : 'LOCAL FILE · ACTIVE' : 'VANILLA PROFILE';
    const profile = $('settings-profile');
    if (profile) {
      profile.textContent = SL.store.themeName();
      profile.classList.toggle('is-accent', !!active);
    }
    updateGameChrome();
  }

  /* ── Boot ────────────────────────────────────────────────── */

  function initClock() {
    const el = $('status-clock');
    if (!el) return;
    function tick() {
      const d = new Date();
      el.textContent = String(d.getHours()).padStart(2, '0') + ':' + String(d.getMinutes()).padStart(2, '0');
    }
    tick();
    if (appState.clockTimer) clearInterval(appState.clockTimer);
    appState.clockTimer = setInterval(tick, 30000);
  }

  function setStatus(text) {
    const el = $('status-message');
    if (el) el.textContent = text;
  }

  function bindGlobalEvents() {
    document.addEventListener('click', function (e) {
      const actionEl = e.target.closest('[data-action]');
      if (actionEl) {
        e.preventDefault();
        handleAction(actionEl.getAttribute('data-action'));
        return;
      }
      const modalClose = e.target.closest('[data-modal-close]');
      if (modalClose) {
        e.preventDefault();
        closeModal(false);
      }
    });
    document.addEventListener('keydown', keydown);
    document.addEventListener('keyup', keyup);
    window.addEventListener('blur', function () {
      SL.game.clearKeys();
      document.querySelectorAll('.dpad-btn.is-pressed, .round-btn.is-pressed').forEach(function (b) { b.classList.remove('is-pressed'); });
      if (appState.view === 'game' && SL.game.isRunning() && !SL.game.isPaused() && SL.game.mode() !== 'dead' && SL.game.mode() !== 'complete') SL.game.pause();
    });
    document.addEventListener('visibilitychange', function () {
      if (document.hidden && appState.view === 'game' && SL.game.isRunning() && !SL.game.isPaused() && SL.game.mode() !== 'dead' && SL.game.mode() !== 'complete') {
        SL.game.pause();
      }
    });
    document.addEventListener('fullscreenchange', function () {
      const btn = $('fullscreen-btn');
      if (btn) btn.setAttribute('aria-pressed', document.fullscreenElement ? 'true' : 'false');
    });
    const fileInput = $('mod-file-input');
    if (fileInput) {
      fileInput.addEventListener('change', function () {
        if (fileInput.files && fileInput.files[0]) SL.mods.installLocalFile(fileInput.files[0]);
        fileInput.value = '';
      });
    }
    document.addEventListener('soullink:mods', function () {
      updateCounts();
      if (appState.view === 'mods') SL.mods.renderInstalled();
    });
    document.addEventListener('soullink:theme', function () {
      updateCounts();
      if (appState.gameMounted && SL.game.isRunning()) SL.game.refreshHud();
    });
    document.addEventListener('soullink:settings', function () {
      syncSound();
      if (appState.view === 'settings') refreshSettingsUI();
    });
    document.addEventListener('soullink:language', function () {
      SL.i18n.apply(document);
      SL.mods.refreshLanguage();
      updateCounts();
      if (appState.view === 'settings') refreshSettingsUI();
    });
    const menu = $('main-menu');
    if (menu) {
      menu.addEventListener('pointerenter', function () {}, true);
    }
    $$('.menu-item').forEach(function (item) {
      item.addEventListener('pointerenter', function () {
        if (SL.audio && SL.audio.isPlaying) SL.audio.sfx('move');
      });
    });
    // First interaction unlocks WebAudio.
    const unlock = function () {
      SL.audio.unlock();
      applyAudioSettings();
      document.removeEventListener('pointerdown', unlock, true);
      document.removeEventListener('keydown', unlock, true);
    };
    document.addEventListener('pointerdown', unlock, true);
    document.addEventListener('keydown', unlock, true);
  }

  function init() {
    SL.i18n.apply(document);
    SL.store.applySettingsClasses();
    SL.store.applyTheme();
    if (isTouch) document.body.classList.add('is-touch');
    if (isAndroidApp) document.body.classList.add('is-android-app');
    document.body.classList.toggle('show-touch-always', SL.store.settings.touchAlways);
    syncSound();
    initClock();
    initAmbient();
    setupApk();
    wireSettings();
    wireTouchControls();
    wireMods();
    bindGlobalEvents();
    SL.mods.init();
    refreshSettingsUI();
    updateCounts();
    updateGameChrome();
    setStatus(t('footer.ready'));

    const hash = (location.hash || '').replace('#', '');
    if (['home', 'settings', 'mods'].indexOf(hash) >= 0) {
      setTimeout(function () { navigate(hash); }, 40);
    }

    // Apply audio once, quietly; browsers keep it suspended until interaction.
    try { applyAudioSettings(); } catch (_) {}

    const boot = $('boot-screen');
    const bootStatus = $('boot-status');
    if (bootStatus) bootStatus.textContent = 'LINKING GAMEBANANA';
    const finishBoot = function () {
      if (appState.booted) return;
      appState.booted = true;
      if (boot) {
        boot.classList.add('is-done');
        setTimeout(function () { boot.setAttribute('aria-hidden', 'true'); }, 600);
      }
      document.body.classList.add('is-ready');
      if (bootStatus) bootStatus.textContent = 'SOUL LINK READY';
    };
    const fontsReady = (document.fonts && document.fonts.ready) ? document.fonts.ready.catch(function () {}) : Promise.resolve();
    Promise.race([
      fontsReady,
      new Promise(function (resolve) { setTimeout(resolve, 1100); })
    ]).then(function () {
      setTimeout(finishBoot, 420);
    });
    setTimeout(finishBoot, 2200);
  }

  window.SL = window.SL || {};
  SL.ui = {
    toast: toast,
    openModal: openModal,
    closeModal: closeModal,
    confirm: confirmDialog,
    navigate: navigate,
    setStatus: setStatus,
    isAndroidApp: isAndroidApp
  };

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init);
  else init();
})();

