setPrompt(text) {
  const value = text || '';
  this.state.prompt = value;
  const el = document.getElementById('game-prompt');
  const label = document.getElementById('game-prompt-text');
  if (!el || !label) return;
  if (value) {
    label.textContent = value;
    el.hidden = false;
  } else {
    el.hidden = true;
  }
}

